    #endregion
    #endregion
    #region | Detect External Storage Media |
    <#
      ${usb0 Disk CIM Instance} = Get-Disk | Where-Object -FilterScript {
        $_.FriendlyName -eq    ${usb0 FriendlyName}              -and `
        $_.UniqueId     -match [Regex]::Escape(${usb0 UniqueId}) -and `
        $_.SerialNumber -eq    ${usb0 SerialNumber}
      }
      if (-not ($null -eq ${usb0 Disk CIM Instance})) {
        ${usb0 Partition CIM Instance} = Get-Partition -DiskNumber ${usb0 Disk CIM Instance}.Number | Select-Object -First 1
        $usb0 = [System.String]${usb0 Partition CIM Instance}.DriveLetter + ":"
      }
    #>
    #endregion

    # ${All Configuration Target Mgmt Cnames} = $ConfigurationData.AllNodes.Where({$null -ne $_.NodeMgmtCname}).NodeMgmtCname
    #if ($null -ne $ConfigurationData) {
    #  ${All Configuration Target Mgmt Cnames} = $ConfigurationData.AllNodes | Where-Object -FilterScript {$null -ne $_.NodeName} | Select-Object -ExpandProperty 'NodeMgmtCname'
    #}

    ${Regex Pattern for Network Adapter Name Precursor} = $(
      '^'
      '%_NodeMgmtCname_% '
      '%_VLAN Title_% '
      '%_Network Adapter Index_%'
      '.txt'
      '$'
    ) -join ''
    ${DNS Server IPv4 Address Collection} = '192.168.55.192'
    #endregion
    @(
      $( # Primordial Unclustered Hyper-V Host and DSC Authoring Station |
        #region |  |
        $NodeMgmtCname = ${DSC Authoring Station Mgmt Cname}
        Write-Host -Object "\____/ `$NodeMgmtCname = '$NodeMgmtCname'-START"; ${Onion4 START} = [System.DateTime]::Now
        $NodeName = [QuickMgmtCnameConversion]::CN($NodeMgmtCname)
        $label = $LabelTheta
        ${Windows Server Image Index} = [System.Int32][WindowsServerImageIndex]::DatacenterDesktopExperience
        ${CertificateID of Cert for Protecting Passwords in MOF File} = Get-ChildItem -Path ${env:Pre-PKI CertFSOs} -ErrorAction 'SilentlyContinue' `
        | Where-Object -FilterScript {
          $_.Name -eq "Encrypt Passwords in MOF for LCM on $NodeMgmtCname.txt"
        } | Get-Content

        # Not really a node-specific variable value, but cuts down on redundant operations: 
        ${All Configuration Target Mgmt Cnames} = $ConfigurationData.AllNodes.Where({$null -ne $_.NodeMgmtCname}).NodeMgmtCname
        #endregion
        @{
          #region | Structural Data Taxonomic Ranks |
          Life          = $true
          SuperEmpire   = 'Microsoft'
          Empire        = 'PM'
          SubEmpire     = 'Windows Server'
          SuperDominion = 'Yes Active Directory should contain an AD Computer account for this system'
          Dominion      = 'Hyper-V'
          Kingdom       = 'Non-HA'
          Phyllum       = ''
          Class         = ''
          Order         = ''
          SuperFamily   = ''
          Family        = ''
          Tribe         = ''
          Genus         = ''
          Species       = 'Primordial Hyper-V Host'
          #endregion
          #region | Essential Key-Value Pairs | Local Configuration Manager |  |
          NodeName = $NodeName
          NodeMgmtCname = $NodeMgmtCname
          'Windows Server Image Index' = ${Windows Server Image Index}
          'Local Configuration Manager-PUSH MODE' = $(
            @{
              Settings = $(
                @{
                  ActionAfterReboot              = 'ContinueConfiguration' # 'StopConfiguration' 'ContinueConfiguration' #
                  AllowModuleOverwrite           = $true
                  CertificateID                  = ${CertificateID of Cert for Protecting Passwords in MOF File}
                  ConfigurationMode              = 'ApplyAndAutoCorrect' # 'ApplyOnly' 'ApplyAndMonitor' 'ApplyAndAutoCorrect' 'MonitorOnly'
                  ConfigurationModeFrequencyMins = 15
                  RefreshFrequencyMins           = 30
                  RebootNodeIfNeeded             = $true
                  RefreshMode                    = 'Push'
                  StatusRetentionTimeInDays      = 20
                  DebugMode                      = @('None')
                }
              )
              SignatureValidation = $(
                @{
                  MetaResource_Title = "$NodeMgmtCname LCMSignatureValidation"
                  TrustedStorePath   = "Cert:\LocalMachine\My\"
                  SignedItemType     = 'Configuration','Module'
                }
              )
            }
          )
          CertificateID = ${CertificateID of Cert for Protecting Passwords in MOF File}
          #endregion

          #region | "Strict PowerShell 5.1 Tracking with System account.ps1" |
          'Strict PowerShell 5.1 Trackers' = $(
            #region |  |
            $ParentPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell"
            #region | Credentials |
            $Target = "$NodeMgmtCname 544"
            $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #endregion
            @(
              $($ValueName = "EnableModuleLogging"; $Key = "$ParentPath\ModuleLogging"; # PowerShell 5.1 Module Logging |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 Module Logging"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = '1'
                  ValueType            = 'Dword'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              $($ValueName = "EnableScriptBlockLogging"; $Key = "$ParentPath\ScriptBlockLogging"; # PowerShell 5.1 ScriptBlock Logging |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 ScriptBlock Logging"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = '1'
                  ValueType            = 'Dword'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              $($ValueName = "EnableScriptBlockInvocationLogging"; $Key = "$ParentPath\ScriptBlockLogging"; # PowerShell 5.1 ScriptBlock Invocation Logging |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 ScriptBlock Invocation Logging"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = '1'
                  ValueType            = 'Dword'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              $($ValueName = "EnableInvocationHeader"; $Key = "$ParentPath\Transcription"; # PowerShell 5.1 Transcription-Enable Invocation Header |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 Transcription-Enable Invocation Header"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = '1'
                  ValueType            = 'Dword'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              $($ValueName = "EnableTranscribing"; $Key = "$ParentPath\Transcription"; # PowerShell 5.1 Transcription-Enable Transcribing |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 Transcription-Enable Transcribing"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = '1'
                  ValueType            = 'String'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              $($ValueName = "EnableTranscripting"; $Key = "$ParentPath\Transcription"; # PowerShell 5.1 Transcription-Enable Transcripting |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 Transcription-Enable Transcripting"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = '1'
                  ValueType            = 'Dword'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              $($ValueName = "OutputDirectory"; $Key = "$ParentPath\Transcription"; # PowerShell 5.1 Transcription-Output Directory |
                #region |  |
                #endregion
                @{
                  Resource_Title       = "PowerShell 5.1 Transcription-Output Directory"
                  ValueName            = $ValueName
                  Key                  = $Key
                  ValueData            = "$env:ProgramData\Transcript-PowerShell 5.1"
                  ValueType            = 'String'
                  Force                = $true
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
            )
          )
          #endregion
          #region | "Local Accounts and Group Membership with System account.ps1" |
          'Local User Accounts' = $(
            @(
              $($Role = 'Administrator'; # Administrators 544 |
                #region |  |
                #region | Credentials |
                $Target = "$NodeMgmtCname 544"
                $UserName = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $Password = [PSCredential]::New($UserName,$pw)

                $Target = "$NodeMgmtCname 220"
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 220
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                #endregion
                @{
                  Resource_Title           = "Local User Account $UserName"
                  UserName                 = $UserName
                  FullName                 = $UserName
                  Password                 = $Password
                  Description              = "Account has complete and unrestricted access to the computer"
                  Disabled                 = $false
                  PasswordChangeNotAllowed = $false
                  PasswordChangeRequired   = $false
                  PasswordNeverExpires     = $true
                  Ensure                   = 'Present'
                  PsDscRunAsCredential     = $PsDscRunAsCredential
                }
              )
              $($Role = 'Administrator'; # Administrators 220 |
                #region | Credentials |
                $Target = $NodeMgmtCname + ' ' + 220
                $UserName = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 220
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $Password = [PSCredential]::New($UserName,$pw)

                $Target = "$NodeMgmtCname 544"
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                @{
                  Resource_Title           = "Local User Account $UserName"
                  UserName                 = $UserName
                  FullName                 = $UserName
                  Password                 = $Password
                  Description              = "Account for updating the 544 administrator"
                  Disabled                 = $false
                  PasswordChangeNotAllowed = $false
                  PasswordChangeRequired   = $false
                  PasswordNeverExpires     = $true
                  Ensure                   = 'Present'
                  PsDscRunAsCredential     = $PsDscRunAsCredential
                }
              )
              $($Role = 'Remote Management User'; # Remote Management Users 580 |
                #region | Credentials |
                $Target = $NodeMgmtCname + ' ' + 580
                $UserName = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 580
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $Password = [PSCredential]::New($UserName,$pw)

                $Target = "$NodeMgmtCname 544"
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                @{
                  Resource_Title           = "Local User Account $UserName"
                  UserName                 = $UserName
                  FullName                 = $UserName
                  Password                 = $Password
                  Description              = "Access WMI resources over management protocols (such as WS-Management via the WinRM service). Applies only to WMI namespaces where access was granted to the user."
                  Disabled                 = $false
                  PasswordChangeNotAllowed = $false
                  PasswordChangeRequired   = $false
                  PasswordNeverExpires     = $true
                  Ensure                   = 'Present'
                  PsDscRunAsCredential     = $PsDscRunAsCredential
                }
              )
            )
          )
          'DISABLED Local User Accounts' = $(
            if ($null -ne $ConfigurationData) {
              if (
                $null -ne $ConfigurationData.AllNodes.Where({
                  $_.NodeMgmtCname -eq $NodeMgmtCname
                }).'Local User Accounts'
              ) {
                $ConfigurationData.AllNodes.Where({
                  $_.NodeMgmtCname -eq $NodeMgmtCname
                }).'Local User Accounts'.Where({
                  $_.UserName -ne [QuickMgmtCnameConversion]::Un($NodeMgmtCname)
                })
              }
            }
          )
          'Local Groups' = $(
            #region | Credentials |
            $Target = "$NodeMgmtCname 544"
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
