                        #>
                        #endregion
                        @( # Binding States of transports and filters on this 'Intel(R) Ethernet Connection (17) I219-LM' network adapter |
                          $($ComponentId = 'ms_implat'; $State = 'Disabled' # Microsoft Network Adapter Multiplexor Protocol |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_l1vhlwf'; $State = 'Enabled' # Nested Network Virtualization |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_lldp'; $State = 'Enabled' # Microsoft LLDP Protocol Driver | IEEE 802.1AB Link Layer Discovery Protocol. Supports Microsoft Data Center Networking (DCN) |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_lltdio'; $State = 'Enabled' # Link-Layer Topology Discovery Mapper I/O Driver |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_msclient'; $State = 'Enabled' # Client for Microsoft Networks |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_pacer'; $State = 'Enabled' # QoS Packet Scheduler |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_rspndr'; $State = 'Enabled' # Link-Layer Topology Discovery Responder |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
