                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_tcpip'; $State = 'Enabled' # Internet Protocol Version 4 (TCP/IPv4) |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              ComponentId          = $ComponentId
                              InterfaceAlias       = $InterfaceAlias
                              State                = $State
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($ComponentId = 'ms_tcpip6'; $State = 'Enabled' # Internet Protocol Version 6 (TCP/IPv6) | Do not disable IPv6 on the network adapter |
                            $Resource_Title = "Binding for $InterfaceName on $NodeMgmtCname-Ensure that network adapter component $ComponentID is $State" -replace '[^a-z0-9- _\.]','\'
                            @{
