                      )
                      '_Firewall Rule Set' = $(@(@{}))
                      '_Firewall Profile Set' = $(@(@{}))
                      'Remote Direct Memory Access' = $(
                        #region |  |
                        $Name = $InterfaceName
                        # Get-NetAdapterRdma -Name $Name | Format-List
                        # Get-NetAdapter | % 'Name' | % {Get-NetAdapterRdma -Name $_ -IncludeHidden}
                        $Resource_Title = "RDMA for interface $Name on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          Enabled              = $true
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Receive Side Scaling' = $(
                        #region |  |
                        $Name  = $InterfaceName
                        # Get-NetAdapterRss -Name $Name
                        # Get-NetAdapter | % 'Name' | % {Get-NetAdapterRss -Name $_ -IncludeHidden}
                        $Resource_Title = "RSS for interface $Name on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          Enabled              = $true
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Receive Segment Coalescing' = $( # Also see the Rsc Advanced Properties on the Network Adapter |
                        #region |  |
                        $Name = $InterfaceName
                        # Get-NetAdapterRsc -Name $Name
                        # Get-NetAdapter | % 'Name' | % {Get-NetAdapterRsc -Name $_ -IncludeHidden | Format-Table -AutoSize}
                        $Resource_Title = "RSC for IPv4 and IPv6 on $Name $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          Protocol             = 'All'
                          State                = $true
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Disable NetBIOS on Network Adapter?' = $(
                        #region |  |
                        $InterfaceAlias = $InterfaceName
                        $Setting = 'Disable'
                        #$Setting = 'Enable'
                        $Resource_Title = "NetBIOS $Setting for $InterfaceAlias on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          InterfaceAlias       = $InterfaceAlias
                          Setting              = $Setting
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Disable WINS Client on Network Adapter' = $(
                        #region |  |
                        $InterfaceAlias = $InterfaceName
                        #endregion
                        @{
                          Resource_Title       = "Eliminate WinsServerAddress for $InterfaceAlias on $NodeMgmtCname"
                          InterfaceAlias       = $InterfaceAlias
                          Address              = 'Exclude to remove all WINS servers'
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      #endregion
                      #region | Collections of Settings for the IPv4 Interface on the Network Adapter |
                      'All Settings on the IPv4 Interface bound to this Network Adapter' = $(
                        #region |  |
                        $AddressFamily = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.AddressFamily]::IPv4
                        $InterfaceAlias = $InterfaceName # The 'InterfaceName' attribute of a Network Adapter is the 'InterfaceAlias' of the Net IP Interface
                        ${State of DHCP Client on IPv4 Interface}  = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.Dhcp]::Enabled

                        $IPAddressFilePath = "$Statics\MaxIP\IPv4\${VLAN Title} ${VLAN ID-Base10 Padded}\$NodeMgmtCname ${Network Adapter Index}.txt"
                        $IsIPAddressFilePresent = Test-Path -Path $IPAddressFilePath
                        if ($IsIPAddressFilePresent) {
                          ${IPAddress No CIDR} = Get-Content -Path $IPAddressFilePath | ConvertTo-DottedDecimalIP | Select-Object -ExpandProperty 'IPAddressToString'
                          ${IPAddress + CIDR} = ${IPAddress No CIDR} + '/' + '22'
                        }
                        <#
                          ${Default Gateway IPv4 Address} = [System.Environment]::GetEnvironmentVariables('Machine')["Default Gateway $_VLAN $AddressFamily Address"]
                          ${_DNS Server IPv4 Address} = $ConfigurationData.AllNodes.Where({
                            $_.NodeCname -eq ${DSC Authoring Station Mgmt Cname}
                          }).'RESERVED IPv4 Addr-DnsServer Global'.IPv4Address
                          $path = "$Statics\IPs\0010 $vlan10\$DomainCtrl00Cname 8 $([aht]::Mc) IP Address.txt"
                          $IsPresent = Test-Path -Path $path
                          if ($IsPresent) {
                            ${DNS Server IPv4 Address in Binary} = Get-Content -Path $path
                            ${DNS Server IPv4 Address} = ConvertTo-DottedDecimalIP -IPAddress ${DNS Server IPv4 Address in Binary} | Select-Object -ExpandProperty 'IPAddressToString'
                          }
                        #>
                        #endregion
                        @{
                          'Consumed by DHCP Server' = $(
                            #region |  |
                            ${Name of DHCP Reservation} = "$NodeMgmtCname ${Network Adapter Index} ${Adapter Hardware Type} within ${VLAN Title}"
                            $Resource_Title = "DHCP Reservation Titled ${Name of DHCP Reservation}"  -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            if ($IsIPAddressFilePresent) {
                              ${IPAddress No CIDR} = Get-Content -Path $IPAddressFilePath | ConvertTo-DottedDecimalIP | Select-Object -ExpandProperty 'IPAddressToString'
                              ${IPAddress + CIDR} = ${IPAddress No CIDR} + '/' + '22'
                              $ScopeId = Get-NetworkSummary -IPAddress ${IPAddress + CIDR} | Select-Object -ExpandProperty 'NetworkAddress' | Select-Object -ExpandProperty 'IPAddressToString'
                              @{
                                'Reservation' = $(
                                  @{
                                    Resource_Title   = $Resource_Title
                                    IPAddress        = ${IPAddress No CIDR}
                                    ScopeID          = $ScopeID
                                    ClientMACAddress = ${MAC Address Hypenated}
                                    AddressFamily    = $AddressFamily
                                    Name             = ${Name of DHCP Reservation}
                                    Ensure           = 'Present'
                                  }
                                )
                                'Net IP Interface-level Options' = $(
                                  @{
                                    'Option 001' = $()
                                    'Option 003' = $()
                                    'Option 006' = $()
                                    'Option 015' = $()
                                  }
                                )
                              }
                            }
                          )
                          'Consumed by DNS Server' = $()
                          'State of DHCP Client on IPv4 Interface' = ${State of DHCP Client on IPv4 Interface}
                          '_This Net IP Interface is transplanted to the ABSTRACTION-BASED network adapter -- IPv4 Interface on Network Adapter' = $()
                          '_This Net IP Interface is transplanted to the ABSTRACTION-BASED network adapter -- Static or Dynamic IP Address of IPv4 Interface' = $()
                          '_This Net IP Interface is transplanted to the ABSTRACTION-BASED network adapter -- Option for Static IPv4 Address' = $()
                          '_This Net IP Interface is transplanted to the ABSTRACTION-BASED network adapter -- IP Address of Default Gateway on Static IPv4 Interface' = $()
                          '_This Net IP Interface is transplanted to the ABSTRACTION-BASED network adapter -- IP Address of DNS Server on Static IPv4 Interface' = $()
                          '_This Net IP Interface is transplanted to the ABSTRACTION-BASED network adapter -- Static IPv4 Route Set' = $()
                          'Large Send Offload version 2' = $(
                            #region |  |
                            $Name = $InterfaceName
                            ${LSOv2 for IPv4 State} = $false
                            # Get-NetAdapter | % 'Name' | % {Get-NetAdapterLso -Name $_} | Format-Table -AutoSize
                            $Resource_Title = "LSOv2 for Net IP Interface $Name in address family $AddressFamily on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            @{
                              Resource_Title       = $Resource_Title
                              Name                 = $Name
                              Protocol             = $AddressFamily
                              State                = ${LSOv2 for IPv4 State}
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                        }
                      )
                      #endregion
                      #region | Collections of Settings for the IPv6 Interface on the Network Adapter |
                      'All Settings on the IPv6 Interface bound to this Network Adapter' = $()
                      #endregion
                    }
                  )
                  $(${VLAN Title} = 'Administrative Control'; ${Network Adapter Index} = '0'; ${Adapter Hardware Type} = [AdapterHardwareType]::Ab;
                    #region |  |
                    ${VLAN ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${VLAN Title}.txt" -ErrorAction 'SilentlyContinue'
                    if ($null -ne ${VLAN ID-Binary}) {
                      ${VLAN ID-Base10} = [System.Convert]::ToInt32(${VLAN ID-Binary},2)
                      ${VLAN ID-Base10 Padded} = ${VLAN ID-Base10}.ToString('0000')
                    }
                    $InterfaceName = "${VLAN Title} ${Network Adapter Index} ${Adapter Hardware Type} Network Adapter"
                    ${MAC Address Raw} = $(
                      $HT = @{
                        Path             = "$Statics\MAC Address Space"
                        Recurse          = $false
                        File             = $true
                        ErrorAction      = 'SilentlyContinue'
                        PipelineVariable = 'file'
                      }
                      Get-ChildItem @HT | Where-Object -FilterScript {
                        $file.Name -eq "$NodeMgmtCname ${VLAN Title} ${Network Adapter Index}.txt"
                      } | Get-Content
                    )
                    ${MAC Address Hypenated} = $(
                      if ($null -ne ${MAC Address Raw}) {
                        $ByteArray = foreach ($i in 0..(${MAC Address Raw}.Length - 1)) {
                          [System.String]${MAC Address Raw}[$($foreach.Current)] + [System.String]${MAC Address Raw}[$($foreach.Current + 1)]  
                          [System.Void]$foreach.MoveNext()
                        }
                        [System.String]::Join('-',$ByteArray).ToUpper()
                      }
                    )
                    ${MAC Address Colons} = ${MAC Address Hypenated} -replace '-',':'
                    $DriverDescription = 'Hyper-V Virtual Ethernet Adapter'
                    $InterfaceDescription = 'Hyper-V Virtual Ethernet Adapter'
                    $PhysicalMediaType = 'Unspecified'
                    <# NOTE | re-write this |
                      Original $InterfaceName follows the pattern
                      $InterfaceName = "vEthernet (${Name Of Hyper-V Switch})"
                      So life for this abstraction-based network adapter began as
                      $InterfaceName = 'vEthernet (SET-enabled External vSwitch)'
                    #>
                    #endregion
                    @{
                      #region | Network Adapter |
                      #region |  |
                      'VLAN Title'            = ${VLAN Title}
                      'Network Adapter Index' = ${Network Adapter Index}.ToLower()
                      'Adapter Hardware Type' = ${Adapter Hardware Type}
                      'VLAN ID-Binary'        = ${VLAN ID-Binary}
                      'VLAN ID-Base10'        = ${VLAN ID-Base10}
                      DriverDescription       = $DriverDescription
                      PhysicalMediaType       = $PhysicalMediaType
                      'MAC Address Raw'       = ${MAC Address Raw}
                      #endregion
                      'Net Adapter Name' = $(
                        #region |  |
                        $NewName = $InterfaceName
                        $Status = 'Up'
                        $Resource_Title = "$NewName on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          NewName              = $NewName
                          MacAddress           = ${MAC Address Hypenated}
                          DriverDescription    = $DriverDescription
                          Status               = $Status
                          PhysicalMediaType    = $PhysicalMediaType
                          InterfaceDescription = $InterfaceDescription
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Net Adapter State' = $(
                        #region |  |
                        $Name = $InterfaceName
                        $State = 'Enabled'
                        $Resource_Title = "Enable $Name Network Adapter on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          State                = $State
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Set of Advanced Properties for this Network Adapter' = $(
                        #region |  |
                        $NetworkAdapterName = $InterfaceName
                        #~# $NetworkAdapterName = 'Administrative Control 0 Abstraction-based Network Adapter'
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | Format-Table -AutoSize
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | % 'DisplayName' | Set-Clipboard
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Format-Table -AutoSize
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Sort-Object -Property 'DisplayName' | Format-Table -AutoSize | clip.exe
                        #endregion
                        @(
                          $($RegistryKeyword = '*JumboPacket'; $RegistryValue = '9014';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Jumbo Packet
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'NetworkAddress'; $RegistryValue = ${MAC Address Raw};
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Network Address
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*IPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPv4 Checksum Offload 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          
                          $($RegistryKeyword = '*IPsecOffloadV2'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPSec Offload 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv4'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload Version 2 (IPv4) 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv6'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload Version 2 (IPv6) 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*MaxRssProcessors'; $RegistryValue = '8';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum Number of RSS Processors 
                            @{
