                              Dhcp                            = ${State of DHCP Client on IPv4 Interface}
                              DirectedMacWolPattern           = $DirectedMacWolPattern
                              EcnMarking                      = $EcnMarking
                              ForceArpNdWolPattern            = $ForceArpNdWolPattern
                              Forwarding                      = $Forwarding
                              IgnoreDefaultRoutes             = $IgnoreDefaultRoutes
                              InterfaceMetric                 = $InterfaceMetric
                              ManagedAddressConfiguration     = $ManagedAddressConfiguration
                              NeighborUnreachabilityDetection = $NeighborUnreachabilityDetection
                              NlMtu                           = $NlMtu
                              OtherStatefulConfiguration      = $OtherStatefulConfiguration
                              RouterDiscovery                 = $RouterDiscovery
                              WeakHostReceive                 = $WeakHostReceive
                              WeakHostSend                    = $WeakHostSend
                              PsDscRunAsCredential            = $PsDscRunAsCredential
                            }
                          )
                          'Static or Dynamic IP Address of IPv4 Interface' = $(
                            #region |  |
                            # Get-NetIPAddress -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias
                            $Resource_Title = "$AddressFamily Address with alias $InterfaceAlias on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            @{
                              Resource_Title       = $Resource_Title
                              AddressFamily        = $AddressFamily
                              InterfaceAlias       = $InterfaceAlias
                              IPAddress            = ${IPAddress + CIDR}
                              KeepExistingAddress  = $false
                              PsDscRunAsCredential = $PsDscRunAsCredential
                              # While the below key-value pairs are *NOT* properties on the 'IPAddress' DSC Resource,
                              # they're used in other areas of this Environment Data file. 
                              Dhcp                 = ${State of DHCP Client on IPv4 Interface}
                              IPAddressFilePath    = $IPAddressFilePath
                            }
                          )
                          'Option for Static IPv4 Address' = $(
                            #region |  |
                            # Get-NetIPAddress -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias | Select-Object -ExpandProperty 'SkipAsSource'
                            $Resource_Title = "IPAddress Option on $InterfaceAlias" -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            @{
                              Resource_Title       = $Resource_Title
                              IPAddress            = ${IPAddress No CIDR}
                              SkipAsSource         = $false
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          'IP Address of Default Gateway on Static IPv4 Interface' = $(
                            #region |  |
                            # ${.psm1 path} = "$env:PMs\NetworkingDsc\9.1.1\DSCResources\DSC_DefaultGatewayAddress\DSC_DefaultGatewayAddress.psm1"
                            # $PSModuleInfo = Import-Module -Name ${.psm1 path} -PassThru -Force
                            # Get-NetDefaultRoute -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias
                            $Resource_Title = "IP Address of Default Gateway to which IPv4 Interface with alias $InterfaceAlias on $NodeMgmtCname will forward extra-subnet traffic" -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            @{
                              Resource_Title       = $Resource_Title
                              AddressFamily        = $AddressFamily
                              InterfaceAlias       = $InterfaceAlias
                              Address              = ${Default Gateway IPv4 Address-DDN}
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          'IP Address of DNS Server on Static IPv4 Interface' = $(
                            #region |  |
                            # ${.psm1 path} = "$env:PMs\NetworkingDsc\9.1.1\DSCResources\DSC_DefaultGatewayAddress\DSC_DefaultGatewayAddress.psm1"
                            # $PSModuleInfo = Import-Module -Name ${.psm1 path} -PassThru -Force
                            # Get-DnsClientServerStaticAddress -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias
                            $Resource_Title = "IP Address of DNS server to which IPv4 Interface with alias $InterfaceAlias on $NodeMgmtCname will transmit DNS queries" -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            @{
                              Resource_Title       = $Resource_Title
                              AddressFamily        = $AddressFamily
                              InterfaceAlias       = $InterfaceAlias
                              Address              = @(${DNS Server IPv4 Address Collection})
                              Validate             = $true
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          'Static IPv4 Route Set' = $(
                            #region |  |
                            # Get-NetRoute -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias
                            #endregion
                            @(
                              $($DestinationPrefix = '255.255.255.255/32'; $NextHop = '0.0.0.0';
                                #region |  |
                                $Resource_Title = "Static Route to $DestinationPrefix starting at $NextHop on Net IP Interface \$InterfaceAlias\ on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                                #endregion
                                @{
                                  Resource_Title       = $Resource_Title
                                  AddressFamily        = $AddressFamily
                                  DestinationPrefix    = $DestinationPrefix
                                  InterfaceAlias       = $InterfaceAlias
                                  NextHop              = $NextHop
                                  PreferredLifetime    = ([System.TimeSpan]::MaxValue)
                                  Publish              = 'No'
                                  RouteMetric          = '256'
                                  Ensure               = 'Present'
                                  PsDscRunAsCredential = $PsDscRunAsCredential
                                }
                              )
                              $($DestinationPrefix = '224.0.0.0/4'; $NextHop = '0.0.0.0';
                                #region |  |
                                $Resource_Title = "Static Route to $DestinationPrefix starting at $NextHop on Net IP Interface \$InterfaceAlias\ on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                                #endregion
                                @{
                                  Resource_Title       = $Resource_Title
                                  AddressFamily        = $AddressFamily
                                  DestinationPrefix    = $DestinationPrefix
                                  InterfaceAlias       = $InterfaceAlias
                                  NextHop              = $NextHop
                                  PreferredLifetime    = ([System.TimeSpan]::MaxValue)
                                  Publish              = 'No'
                                  RouteMetric          = '256'
                                  Ensure               = 'Present'
                                  PsDscRunAsCredential = $PsDscRunAsCredential
                                }
                              )
                            )
                          )
                          '_Later Is Now Static IPv4 Route Set' = $(
                            #region |  |
                            #endregion
                            @(
                              $(
                                @{
                                  Resource_Title       = "Static Route on Net IP Interface \$InterfaceAlias\ on $NodeMgmtCname"
                                  AddressFamily        = $AddressFamily
                                  DestinationPrefix    = "10.$Octet2.13.255/32"
                                  InterfaceAlias       = $InterfaceAlias
                                  NextHop              = '0.0.0.0'
                                  PreferredLifetime    = ([System.TimeSpan]::MaxValue)
                                  Publish              = 'No'
                                  RouteMetric          = '256'
                                  Ensure               = 'Present'
                                  PsDscRunAsCredential = $PsDscRunAsCredential
                                }
                              )
                              $(
                                @{
                                  Resource_Title       = "Static Route on Net IP Interface \$InterfaceAlias\ on $NodeMgmtCname"
                                  AddressFamily        = $AddressFamily
                                  DestinationPrefix    = "10.$Octet2.12.2/32"
                                  InterfaceAlias       = $InterfaceAlias
                                  NextHop              = '0.0.0.0'
                                  PreferredLifetime    = ([System.TimeSpan]::MaxValue)
                                  Publish              = 'No'
                                  RouteMetric          = '256'
                                  Ensure               = 'Present'
                                  PsDscRunAsCredential = $PsDscRunAsCredential
                                }
                              )
                              $(
                                @{
                                  Resource_Title       = "Static Route on Net IP Interface \$InterfaceAlias\ on $NodeMgmtCname"
                                  AddressFamily        = $AddressFamily
                                  DestinationPrefix    = "10.$Octet2.12.0/23"
                                  InterfaceAlias       = $InterfaceAlias
                                  NextHop              = '0.0.0.0'
                                  PreferredLifetime    = ([System.TimeSpan]::MaxValue)
                                  Publish              = 'No'
                                  RouteMetric          = '256'
                                  Ensure               = 'Present'
                                  PsDscRunAsCredential = $PsDscRunAsCredential
                                }
                              )
                              $(
                                @{
                                  Resource_Title       = "Static Route on Net IP Interface \$InterfaceAlias\ on $NodeMgmtCname"
                                  AddressFamily        = $AddressFamily
                                  DestinationPrefix    = '0.0.0.0/0'
                                  InterfaceAlias       = $InterfaceAlias
                                  NextHop              = ${Default Gateway IPv4 Address}
                                  PreferredLifetime    = ([System.TimeSpan]::MaxValue)
                                  Publish              = 'No'
                                  RouteMetric          = '256'
                                  Ensure               = 'Present'
                                  PsDscRunAsCredential = $PsDscRunAsCredential
                                }
                              )
                            )
                          )
                          'Large Send Offload version 2' = $(
                            #region |  |
                            $Name = $InterfaceName
                            ${LSOv2 for IPv4 State} = $false
                            # Get-NetAdapter | % 'Name' | % {Get-NetAdapterLso -Name $_} | Format-Table -AutoSize
                            $Resource_Title = "LSOv2 for Net IP Interface $Name in address family $AddressFamily on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            @{
                              Resource_Title       = $Resource_Title
                              Name                 = $Name
                              Protocol             = $AddressFamily
                              State                = ${LSOv2 for IPv4 State}
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                        }
                      )
                      #endregion
                      #region | Collections of Settings for the IPv6 Interface on the Network Adapter |
                      'All Settings on the IPv6 Interface bound to this Network Adapter' = $()
                      #endregion
                    }
                  )
                  $(${VLAN Title} = 'iSCSI Storage'; ${Network Adapter Index} = '0'; ${Adapter Hardware Type} = [AdapterHardwareType]::Mc;
                    #region |  |
                    ${VLAN ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${VLAN Title}.txt" -ErrorAction 'SilentlyContinue'
                    if ($null -ne ${VLAN ID-Binary}) {
                      ${VLAN ID-Base10} = [System.Convert]::ToInt32(${VLAN ID-Binary},2)
                      ${VLAN ID-Base10 Padded} = ${VLAN ID-Base10}.ToString('0000')
                    }
                    $InterfaceName = "${VLAN Title} ${Network Adapter Index} ${Adapter Hardware Type} Network Adapter"
                    ${MAC Address Raw} = $(
                      $HT = @{
                        Path             = "$Statics\MAC Address Space"
                        Recurse          = $false
                        File             = $true
                        ErrorAction      = 'SilentlyContinue'
                        PipelineVariable = 'file'
                      }
                      Get-ChildItem @HT | Where-Object -FilterScript {
                        $file.Name -eq "$NodeMgmtCname ${VLAN Title} ${Network Adapter Index}.txt"
                      } | Get-Content
                    )
                    ${MAC Address Hypenated} = $(
                      if ($null -ne ${MAC Address Raw}) {
                        $ByteArray = foreach ($i in 0..(${MAC Address Raw}.Length - 1)) {
                          [System.String]${MAC Address Raw}[$($foreach.Current)] + [System.String]${MAC Address Raw}[$($foreach.Current + 1)]  
                          [System.Void]$foreach.MoveNext()
                        }
                        [System.String]::Join('-',$ByteArray).ToUpper()
                      }
                    )
                    ${MAC Address Colons} = ${MAC Address Hypenated} -replace '-',':'
                    $DriverDescription = 'Realtek PCIe GbE Family Controller'
                    $PhysicalMediaType = '802.3'
                    #endregion
                    @{
                      #region | Network Adapter |
                      #region |  |
                      'VLAN Title'            = ${VLAN Title}
                      'Network Adapter Index' = ${Network Adapter Index}.ToLower()
                      'Adapter Hardware Type' = ${Adapter Hardware Type}
                      'VLAN ID-Binary'        = ${VLAN ID-Binary}
                      'VLAN ID-Base10'        = ${VLAN ID-Base10}
                      DriverDescription       = $DriverDescription
                      PhysicalMediaType       = $PhysicalMediaType
                      'MAC Address Raw'       = ${MAC Address Raw}
                      #endregion
                      'Net Adapter Name' = $(
                        #region |  |
                        $NewName = $InterfaceName
                        $Status = 'Disconnected'
                        $Resource_Title = "$NewName on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          NewName              = $NewName
                          MacAddress           = ${MAC Address Hypenated}
                          DriverDescription    = $DriverDescription
                          Status               = $Status
                          PhysicalMediaType    = $PhysicalMediaType
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Net Adapter State' = $(
                        #region |  |
                        $Name = $InterfaceName
                        $State = 'Enabled'
                        $Resource_Title = "Enable $Name Network Adapter on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          State                = $State
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Set of Advanced Properties for this Network Adapter' = $(
                        #region |  |
                        $NetworkAdapterName = $InterfaceName
                        #~# $NetworkAdapterName = 'Virtualized Workloads 0 Motherboard-connected Network Adapter'
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | Format-Table -AutoSize
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | % 'DisplayName' | Set-Clipboard
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Format-Table -AutoSize
                        #~# Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Sort-Object -Property 'DisplayName' | Format-Table -AutoSize
                        #endregion
                        @(
                          $($RegistryKeyword = '*SpeedDuplex'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Speed & Duplex. Switch link speed and duplex. '0' means auto-negotiation is selected, configures the Tx and Rx sides to agree on the best speed. 
                            # '6' means "1.0 Gbps Full Duplex". Just use auto-negotiation. 
                            # I once resolved an issue at the help desk where the root cause ended up being mice that partially chewed through an Ethernet cable. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'NetworkAddress'; $RegistryValue = ${MAC Address Raw};
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Network Address changes the MAC address of network card.
                            # Do not input the broadcast MAC address or a multicast MAC address. "If so, the driver stops to load after the wrong MAC address changed"
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*IPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPv4 Checksum Offload. OS can offload IPv4 checksum calculation to hardware instead of calculating in software. 
                            # '3' means IPv4 Checksum Offload is enabled for both transmit (Tx) and receive (Rx) data streams. 
                            # If 'IPv4 Checksum Offload' is disabled then the OS uses its software routine to calculate the checksum, which is guaranteed to be slower. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TCPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # TCP Checksum Offload (IPv4)
                            # OS offloads IPv4 TCP checksum calculation to hardware. 
                            # Same options as IPv4 Checksum Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv4)
                            # OS offloads IPv4 UDP checksum calculation to hardware. 
                            # Same options as IPv4 Checksum Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv4'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload v2 (IPv4)
                            # OS offloads large TCP/IPv4 segmentation from software to hardware. 
                            # This could improve transfer speed and reduce CPU utilization. 
                            # See the JumboPacket/JumboFrames section for the rationale behind disabling LSOv2
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv6'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload v2 (IPv6). Same idea as LSOv2 for IPv4. 
                            # See the JumboPacket/JumboFrames section for the rationale behind disabling LSOv2
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*FlowControl'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Flow Control. If the network shows signs of congestion, Flow Control can pause/stop TX side sending to prevent lost packets.
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*PriorityVLANTag'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Priority & VLAN
                            # "Priority & VLAN Enabled" means both Priority and VLAN are enabled
                            # "Priority Enabled" means VLAN ID on network adapter is set to Zero and only Priority is supported
                            # "VLAN Enabled" means only changing VLAN IDs is supported and Priority is locked to 0
                            # "Priority & VLAN Disabled" means "Both Priority and VLAN are disabled", which probably means VLAN ID on network adapter is 0, as is the Priority value.
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*InterruptModeration'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Interrupt Moderation. From RealTek's documentation: 
                            # "The interrupts are automatically trigger in a period. This reduces CPU utilization and improve throughput."
                            # Good enough for me. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*ReceiveBuffers'; $RegistryValue = '512';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Buffers. This is bullshit: 
                            # Driver for Windows Server 2022 limited ReceiveBuffers to 1024
                            # Driver for Windows Server 2025 limits ReceiveBuffers to 512!
                            # RealTek is rotten to the core. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TransmitBuffers'; $RegistryValue = '128';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Transmit Buffers. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*JumboPacket'; $RegistryValue = '9014';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Jumbo Frame. DisplayName is 'Jumbo Frame'. RegistryKeyword is '*JumboPacket'. 
                            # RealTek's FAQ: 
                            ## Q. What is Jumbo Frame What is the purpose of this feature
                            ## A. This feature is for performance. It increases the maximum length of one packet.
                            ##
                            ## It is out of ethernet specific and has ethernet switch/hub compatibility. If the ethernet switch could not support the jumbo frame, the packet will be discarded.
                            ## Users may directly link the 2 machines to avoid the maximum length limitation but this also limit the connectivity.
                            ## Driver will disable Large Send Offload (IPv4) after user enables this feautre, TCP/IP could has better performance if it use jumbo frame without large send.
                            ## If users enable both of them, the driver automatically chooses Jumbo Packet.
                            ## For switch compatibility and TCP/IP performance, it is better to use Large Send Offload (IPv4) rather than Jumbo frame
                            ##
                            ## Althrough, the Advanced page has Disable, 2KB MTU, 3KB MTU, ... 7KB MTU. Driver will not enable the option which exceeds the NIC hardware limitation.
                            ## If exceeds, driver automatically decreases the length to a proper value.
                            ## How to verify jumboframe works :
                            ## 1. Both sides enable the jumboframe to a identical value.
                            ## If two sides has different jumboframe length limitation, use smaller value.
                            ## For example, cardbus 8169 and PCI 8169 should use 3KB.
                            ## 2. Both side must disable firewall.
                            ## 3. To avoid switch/hub compatiblity issue , please connect the two NICs directly.
                            ## 4. Ping a large packet to the other machine. Ping xxx.xxx.xxx.xxx -l 65000
                            ## 5. If responses successfully, the jumboframe works.
                            # So elect either JumboFrames or LSOv2, but not both. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'S5WakeOnLan'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # First some vocab. PHY is not an acronym. It's short for "PHYsical layer transceiver", which is a hardware component frequently built into 
                            # Ethernet devices. Here's documentation on PHYs: 'https://www.ti.com/en-us/design-development/educational-resources/video/6116551204001' 
                            # Shutdown Wake-On-Lan. 
                            ## "Enabled" means system could wakeup from shutdown by magic packet. PHY component of Ethernet hardware kept ON. 
                            ## "Disabled" means PHY turn off to reduce power consumption but could NOT wakeup by magic packet
                            # "Shutdown Wake-On-Lan" is for power conservation. Affects shutdown mode (S5) power consumption. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'AutoDisableGigabit'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Auto Disable Gigabit
                            ## Disabled : Always enable gigabit
                            ## Re-Link, Battery : auto disabled gigabit when re-link and using battery
                            ## Re-Link, Battery or AC : auto disabled gigabit when re-link
                            ## When users change the setting to Re-Link and user unplugs and plugs network cable again, the driver will automatically disable gigabit capability.
                            ## Gigabit has much higher power consumption than 10/100 MBps. For notebook users, it is recommended to turn on this to reduce power consumption.
                            ## This option MUST change to Re-Link to enable Auto Disable Phy"
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'PowerSavingMode'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Power Saving Mode
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSS'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Side Scaling
                            ## 1. This feature is for better CPU utilization balance while internet browsing and file copying.
                            ## 2. This is especially good for complex homepage content with a lot of pictures. Because OS will create one TCP connection for each picture. Those TCP connections will dispatch to different CPUs. From driver layer to application layer, data transfer and picture decoding runs on different CPU.
                            ## 3. This feature could not incorease total throughput. It designed for better CPU utilization. The network performance benchmark tool may show that the total throughput decreased when RSS enabled.
                            ## 4. It is recommend end-user who care better CPU utilization to enable this feature.
                            ## 5. When RSS enabled, driver allocates two distinct receive buffer. The receiving buffer size is two times than RSS disabled.
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )




                          $($RegistryKeyword = 'RegVlanID'; $RegistryValue = ${VLAN ID-Base10};
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # VLAN ID
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*EEE'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Energy-Efficient Ethernet. Disable this nonsense, whatever it is. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'EnableGreenEthernet'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Green Ethernet. Disable this nonsense, whatever it is. 
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TCPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # TCP Checksum Offload (IPv6)
                            # OS offloads IPv4 TCP checksum calculation to hardware. 
                            # Same options as IPv4 Checksum Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )

                          $($RegistryKeyword = '*ModernStandbyWoLMagicPacket'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Wake on magic packet when system is in the S0ix power state
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*NumRssQueues'; $RegistryValue = '4';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum Number of RSS Queues
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*PMARPOffload'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # ARP Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*PMNSOffload'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # NS Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*WakeOnMagicPacket'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Wake on Magic Packet
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*WakeOnPattern'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Wake on pattern match-Not quite sure what this means
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'WolShutdownLinkSpeed'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # WOL & Shutdown Link Speed
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                        )
                      )
