                            $Forwarding                      = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.Forwarding]::Disabled
                            $IgnoreDefaultRoutes             = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.IgnoreDefaultRoutes]::Disabled
                            $InterfaceMetric                 = [System.Int32]25
