                            $WeakHostSend                    = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.WeakHostSend]::Disabled
                            # Get-NetIPInterface -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias | Format-List -Property 'InterfaceAlias','AddressFamily','AdvertiseDefaultRoute','Advertising','AutomaticMetric','Dhcp','DirectedMacWolPattern','EcnMarking','ForceArpNdWolPattern','Forwarding','IgnoreDefaultRoutes','InterfaceMetric','ManagedAddressConfiguration','NeighborUnreachabilityDetection','NlMtu','OtherStatefulConfiguration','RouterDiscovery','WeakHostReceive','WeakHostSend'
                            $Resource_Title = "$AddressFamily Interface with alias $InterfaceAlias on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                            #endregion
