                              Resource_Title                  = $Resource_Title
                              AddressFamily                   = $AddressFamily
                              InterfaceAlias                  = $InterfaceAlias
                              AdvertiseDefaultRoute           = $AdvertiseDefaultRoute
                              Advertising                     = $Advertising
                              AutomaticMetric                 = $AutomaticMetric
