          #region | !"Windows Features, Roles, and Role Services-! Blank DependsOn with System account.ps1" |
          Purpose_0f_Instance = 'Primordial_DSC_Push_Server'
          Configuration_Names = @('Primordial_DSC_Push_Server')
          'Windows Features, Roles, and Role Services' = [System.Object[]]$(
            #region | Credentials |
            $Target = "$NodeMgmtCname 544"
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Credential = [PSCredential]::New($un,$pw)

            $Target = "$NodeMgmtCname 544"
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #region | character sequence replacements |
            ${Hyper-V HT} = ${Clone Me Hyper-V HT}.Clone()
            ${Hyper-V HT}['Resource_Title'] = ${Hyper-V HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            #${Hyper-V HT}['IncludeAllSubfeature'] = $true
            ${Hyper-V HT}.Add('Credential',$Credential)
            ${Hyper-V HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${RSAT-Hyper-V-Tools HT} = ${Clone Me RSAT-Hyper-V-Tools HT}.Clone()
            ${RSAT-Hyper-V-Tools HT}['Resource_Title'] = ${RSAT-Hyper-V-Tools HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${RSAT-Hyper-V-Tools HT}.Add('Credential',$Credential)
            ${RSAT-Hyper-V-Tools HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${Hyper-V-Tools HT} = ${Clone Me Hyper-V-Tools HT}.Clone()
            ${Hyper-V-Tools HT}['Resource_Title'] = ${Hyper-V-Tools HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${Hyper-V-Tools HT}.Add('Credential',$Credential)
            ${Hyper-V-Tools HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${Hyper-V-PowerShell HT} = ${Clone Me Hyper-V-PowerShell HT}.Clone()
            ${Hyper-V-PowerShell HT}['Resource_Title'] = ${Hyper-V-PowerShell HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${Hyper-V-PowerShell HT}.Add('Credential',$Credential)
            ${Hyper-V-PowerShell HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${RSAT-ADCS HT} = ${Clone Me RSAT-ADCS HT}.Clone()
            ${RSAT-ADCS HT}['Resource_Title'] = ${RSAT-ADCS HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${RSAT-ADCS HT}.Add('Credential',$Credential)
            ${RSAT-ADCS HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            # "RSAT-ADCS-Mgmt" is required by 'PSPKI' Windows PowerShell non-DSC module
            ${RSAT-ADCS-Mgmt HT} = ${Clone Me RSAT-ADCS-Mgmt HT}.Clone()
            ${RSAT-ADCS-Mgmt HT}['Resource_Title'] = ${RSAT-ADCS-Mgmt HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${RSAT-ADCS-Mgmt HT}.Add('Credential',$Credential)
            ${RSAT-ADCS-Mgmt HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)
            #endregion
            if ( # Desktop Experience |
              -not (${Windows Server Image Index} % 2)
            ) {
              @(
                ${Hyper-V HT}
                ${RSAT-Hyper-V-Tools HT}
                ${Hyper-V-Tools HT}
                ${Hyper-V-PowerShell HT}
                ${RSAT-ADCS HT}
                ${RSAT-ADCS-Mgmt HT}
              )
            } else { # Server Core |
              @(
                ${Hyper-V HT}
                ${RSAT-Hyper-V-Tools HT}
                ${Hyper-V-PowerShell HT}
              )
            }
          )
          #endregion

          #region | "Virtual Switch Clade 00 with System account.ps1" |
          'Virtual Switch Clade 00---Abstraction-based NetAdapter from Motherboard-connected Intel NIC' = $(
            if ($null -ne $ConfigurationData) {
              #region | Credentials  |
              $Target = "$NodeMgmtCname 544"
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion

              ${Allow ManagementOS Network Adapter Details} = (
                $ConfigurationData.AllNodes | Where-Object -FilterScript {
                  $_.NodeMgmtCname -eq $NodeMgmtCname
                }
              ).'Network Refined v2'.'Adapters Config' | Where-Object -FilterScript {
                $_.'Adapter Hardware Type'    -eq    [AdapterHardwareType]::Mc   -and `
                $_.'Net Adapter Name'.NewName -match '^Administrative Control 0'
              }

              ${Virtual Switch Name} = 'SET-enabled External vSwitch'
              ${Virtual Switch Type} = 'External'
              ${Create Abstraction-based Network Adapter for OS Instance in HvH Partition to communicate with the Virtual Switch?} = $true

              $Resource_Title = "${Virtual Switch Type} vSwitch ${Virtual Switch Name} on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
              ${vSwitch UUID .txt File BaseName} = $Resource_Title -replace '\\','_'
              ${vSwitch UUID .txt File FullName} = "$Statics\vHW\sw\${vSwitch UUID .txt File BaseName}.txt"
              #${Is vSwitch UUID Already Defined} = Test-Path -Path ${vSwitch UUID .txt File FullName}
              if (
                #${Is vSwitch UUID Already Defined}
                $true
              ) {
                ${Is vSwitch UUID Already Defined} = Test-Path -Path ${vSwitch UUID .txt File FullName}
                if (${Is vSwitch UUID Already Defined}) {
                  ${Virtual Switch Universally Unique ID} = Get-Content -Path ${vSwitch UUID .txt File FullName}
                }
                #region |  |
                $Name = ${Virtual Switch Name}
                $Type = ${Virtual Switch Type}
                $NetAdapterName = ${Allow ManagementOS Network Adapter Details}.'Net Adapter Name'.NewName
                $AllowManagementOS = ${Create Abstraction-based Network Adapter for OS Instance in HvH Partition to communicate with the Virtual Switch?}
                $Id = ${Virtual Switch Universally Unique ID}
                # [System.Guid]::NewGuid() | Select-Object -ExpandProperty 'Guid'
                #endregion
                @{
                  Resource_Title              =     $Resource_Title
                  Name                        =     ${Virtual Switch Name}
                  Type                        =     ${Virtual Switch Type}
                  NetAdapterName              =     $NetAdapterName
                  AllowManagementOS           =     $AllowManagementOS
                  BandwidthReservationMode    =     'Absolute'
                  EnableEmbeddedTeaming       =     $true
                  Id                          =     $Id
                  LoadBalancingAlgorithm      =     'Dynamic'
                  Ensure                      =     'Present'
                  PsDscRunAsCredential        =     $PsDscRunAsCredential
                }
              }
            }
          )
