          #region | "VLAN Settings on Abstraction-based Network Adapter Connecting Parent Partition to External vSwitch with System account.ps1" |
          'VLAN Settings on Abstraction-based Network Adapter Connecting Parent Partition to External vSwitch' = $(
            if ($null -ne $ConfigurationData) {
              ${Virtual Switch Clade 00---Abstraction-based NetAdapter from Motherboard-connected Intel NIC} = $ConfigurationData.AllNodes.Where({$_.Dominion -eq 'Hyper-V'}).'Virtual Switch Clade 00---Abstraction-based NetAdapter from Motherboard-connected Intel NIC'
              if (
                $null -ne ${Virtual Switch Clade 00---Abstraction-based NetAdapter from Motherboard-connected Intel NIC}
              ) {
                #region |  |
                #region | Credentials |
                $Target = "$NodeMgmtCname 544"
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                # ${Virtual Switch Clade 00---Abstraction-based NetAdapter from Motherboard-connected Intel NIC}

                ${Allow ManagementOS Network Adapter Details} = (
                  $ConfigurationData.AllNodes | Where-Object -FilterScript {
                    $_.NodeMgmtCname -eq $NodeMgmtCname
                  }
                ).'Network Refined v2'.'Adapters Config' | Where-Object -FilterScript {
                  $_.'Adapter Hardware Type'    -eq    [AdapterHardwareType]::Mc   -and `
                  $_.'Net Adapter Name'.NewName -match '^Administrative Control 0'
                }
                # VLAN ID of physical Network Adapter whose IP Interface is being disassociated
                # and re-bound (re-binded?) to the newly-created virtual Network Adapter: 
                ${Virtual Switch Name} = 'SET-enabled External vSwitch'

                ${Allow ManagementOS Network Adapter Details} = (
                  $ConfigurationData.AllNodes | Where-Object -FilterScript {
                    $_.NodeMgmtCname -eq $NodeMgmtCname
                  }
                ).'Network Refined v2'.'Adapters Config' | Where-Object -FilterScript {
                  $_.'Adapter Hardware Type'    -eq    [AdapterHardwareType]::Mc   -and `
                  $_.'Net Adapter Name'.NewName -match '^Administrative Control 0'
                }

                ${Virtual Switch Name} = 'SET-enabled External vSwitch'
                ${Virtual Switch Type} = 'External'
                ${Create Abstraction-based Network Adapter for OS Instance in HvH Partition to communicate with the Virtual Switch?} = $true

                $Resource_Title = "${Virtual Switch Type} vSwitch ${Virtual Switch Name} on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                ${vSwitch UUID .txt File BaseName} = $Resource_Title -replace '\\','_'
                ${vSwitch UUID .txt File FullName} = "$Statics\vHW\sw\${vSwitch UUID .txt File BaseName}.txt"
                ${Is vSwitch UUID Already Defined} = Test-Path -Path ${vSwitch UUID .txt File FullName}
                if (${Is vSwitch UUID Already Defined}) {
                  ${Virtual Switch Universally Unique ID} = Get-Content -Path ${vSwitch UUID .txt File FullName}
                }
                #endregion
                @{
                  Resource_Title            =      $Resource_Title
                  Id                        =      ${Virtual Switch Universally Unique ID}
                  Name                      =      ${Virtual Switch Name}
                  VMName                    =      'ManagementOS'
                  AdapterMode               =      'Access'
                  VlanId                    =      ${Allow ManagementOS Network Adapter Details}.'VLAN ID-Base10'
                  #AllowedVlanIdList        =      "10,12,14,16,18,20"
                  #NativeVlanId             =      "1"
                  #PrimaryVlanId            =      "10"
                  #SecondaryVlanId          =      ""
                  #SecondaryVlanIdList      =      ""
                  PsDscRunAsCredential      =      $PsDscRunAsCredential
                }
              }
            }
          )
          #endregion

          #region | "Hypervisor Config without Live Migration on UnClustered Hyper-V Host with System account.ps1" |
          'Hyper-V Host Phase I' = $(
            ${Is Mac Address Space Defined} = Test-Path -Path "$Statics\MAC Address Space\$NodeMgmtCname.txt"
            if (${Is Mac Address Space Defined}) {
              #region |  |
              ${MAC Address Space Bits in Base2} = Get-Content -Path "$Statics\MAC Address Space\$NodeMgmtCname.txt"
              ${Qty of MAC Address Space Bits in Base2} = ${MAC Address Space Bits in Base2}.Length
              ${Qty of MAC Address Bits for Adapter} = 24 - ${Qty of MAC Address Space Bits in Base2}

              ${MAC Address Bits for Adapter in Base2 (Max)} = (1..${Qty of MAC Address Bits for Adapter} | ForEach-Object -Process {'1'}) -join ''
              ${MAC Address Bits 25-48 in Base2-Upper Bound} = ${MAC Address Space Bits in Base2} + ${MAC Address Bits for Adapter in Base2 (Max)}
              ${MAC Address Bits 25-48 in Base10-Upper Bound} = [System.Convert]::ToInt32(${MAC Address Bits 25-48 in Base2-Upper Bound},2)
              ${MAC Address Bits 25-48 in Base16-Upper Bound} = '{0,0:x4}' -f ${MAC Address Bits 25-48 in Base10-Upper Bound}
              $MacAddressMaximum = '00155d' + ${MAC Address Bits 25-48 in Base16-Upper Bound}

              ${MAC Address Bits for Adapter in Base2 (Min)} = (1..${Qty of MAC Address Bits for Adapter} | ForEach-Object -Process {'0'}) -join ''
              ${MAC Address Bits 25-48 in Base2-Lower Bound} = ${MAC Address Space Bits in Base2} + ${MAC Address Bits for Adapter in Base2 (Min)}
              ${MAC Address Bits 25-48 in Base10-Lower Bound} = [System.Convert]::ToInt32(${MAC Address Bits 25-48 in Base2-Lower Bound},2)
              ${MAC Address Bits 25-48 in Base16-Lower Bound} = '{0,0:x4}' -f ${MAC Address Bits 25-48 in Base10-Lower Bound}
              $MacAddressMinimum = '00155d' + ${MAC Address Bits 25-48 in Base16-Lower Bound}

              #region | Credentials |
              $Target = "$NodeMgmtCname 544"
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion
              #endregion
              @{
                Resource_Title            = "Hyper-V Host on $NodeMgmtCname prior to domain-join"
                IsSingleInstance          = 'Yes'
                EnableEnhancedSessionMode = $true
                #MacAddressMaximum         = $MacAddressMaximum
                #MacAddressMinimum         = $MacAddressMinimum
                VirtualMachinePath        = ${env:VM Folder Path}
                VirtualHardDiskPath       = ${env:VHD Folder Path}
                NumaSpanningEnabled       = $true
                PsDscRunAsCredential      = $PsDscRunAsCredential
              }
            }
          )
          #endregion
          #region | "New Hyper-V VM + Components with System account.ps1" |
          'All VM-related Environment Data for All VMs' = $(
            if ($null -ne $ConfigurationData) {
              #region |  |
              ${Collection of Environment Data for All VMs} = $ConfigurationData.AllNodes | Where-Object -FilterScript {$_.Empire -eq 'VM'}
              #endregion
              foreach (${All Environment Data for this Individual VM} in ${Collection of Environment Data for All VMs}) {
                @{
                  'ConfigTargetMgmtCname'                       = ${All Environment Data for this Individual VM}.NodeMgmtCname
                  'System Disk'                                 = ${All Environment Data for this Individual VM}.'System Disk'
                  'Non-System Virtual Disks'                    = ${All Environment Data for this Individual VM}.'OS-level non-system disks'
                  'Hyper-V Virtual Machine'                     = ${All Environment Data for this Individual VM}.'Hyper-V Virtual Machine'
                  'vCPU in Virtual Machine'                     = ${All Environment Data for this Individual VM}.'vCPU in Virtual Machine'
                  'Hyper-V Virtual Network Adapter Definitions' = ${All Environment Data for this Individual VM}.'Hyper-V Virtual Network Adapter Definitions'
                }
              }
            }
          )
          #endregion



          #region | DSC AUTHORING STATION ONLY |
          #region | "Accumulated System VHDX Cascades with System account.ps1" |
          'VhdxFileFromIsoImage Set' = $(
            if ($null -ne $ConfigurationData) {
              #region |  |
              $IsoFilePath = "$env:DSC_CFG_ROOT\Hyper-V Prep\Images\Patched\Windows Server 2025.iso"
              $IsIsoFilePresent = Test-Path -Path $IsoFilePath

              $AllExcludedDscResourceModuleZips = $ExcludedDscResourceModuleZIPs + $AuthoredDscResourceModuleZIPs | Sort-Object | Get-Unique
              $FullNames0 = Get-ChildItem -Path "$env:DSC_CFG_ROOT\DSC Resource Modules\*.zip" -Exclude $AllExcludedDscResourceModuleZips -ErrorAction 'SilentlyContinue' | Select-Object -ExpandProperty 'FullName'
              $FullNames1 = Get-Item -Path "$env:DSC_CFG_ROOT\Modules\5.1\PSPKI.zip" -ErrorAction 'SilentlyContinue' | Select-Object -ExpandProperty 'FullName'
              #$DscResModZipFilePaths = $FullNames0 + $FullNames1
              $DscResModZipFilePaths = $FullNames0

              #region | Credentials |
              $Target = "$NodeMgmtCname 544"
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion
              #endregion
              if (
                ($null -ne $DscResModZipFilePaths) -and ($IsIsoFilePresent)
              ) {
                ${Windows Server Image Index Set} = $ConfigurationData.AllNodes.Where({
                  $_.Life        -eq $true            -and `
                  $_.SuperEmpire -eq 'Microsoft'      -and `
                  $_.Empire      -eq 'VM'             -and `
                  $_.SubEmpire   -eq 'Windows Server'
                }).'Windows Server Image Index' | Sort-Object | Get-Unique
                foreach (${Windows Server Image Index} in ${Windows Server Image Index Set}) {
                  #region |  |
                  $Resource_Title = "Deploy .vhdx file of Server 2025 edition with image index ${Windows Server Image Index} into \VHDX 0-General\ directory"
                  $VhdxFilePath = "$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 0-General\${Windows Server Image Index}\Windows Server 2025.vhdx"
                  #endregion
                  @{
                    Resource_Title          =   $Resource_Title
                    VhdxFilePath            =   $VhdxFilePath
                    IndexOfImage            =   ${Windows Server Image Index}
                    IsoFilePath             =   $IsoFilePath
                    DscResModZipFilePaths   =   $DscResModZipFilePaths
                    Ensure                  =   'Present'
                    PsDscRunAsCredential    =   $PsDscRunAsCredential
                  }
                }
              }
            }
          )
          'System VHDX Cascades' = $(
            if ($null -ne $ConfigurationData) {
              ${System VHDX Cascades} = $ConfigurationData.AllNodes.Where({$_.Empire -eq 'VM'}).'System VHDX Cascade'
              if ($null -ne ${System VHDX Cascades}) {
                $ConfigurationData.AllNodes.Where({
                  $_.Empire -eq 'VM'
                }).'System VHDX Cascade'
              }
            }
          )
          #endregion
          #region | VHDX Excluded from Storage Spaces Virtual Disk participation-DSC Configuration Root with System account.ps1 |
          'No SSVDs-DSC Config Root Set' = $(
            if ($null -ne $ConfigurationData) {
              #${No SSVDs-DSC Config Root Set} = $ConfigurationData.AllNodes.Where({$_.Empire -eq 'VM'}).'OS-level non-system disks'.Where({$_.'Storage Resiliency Reference' -eq 'No SSVD-DSC config root'})

            }
          )
          #endregion

          #region | "IPv4 Address Space Definitions with System account.ps1" "Sample Without Replacement Random IPv4 Addresses to Ensure Uniqueness with System account.ps1" |
          'Outline Random Exclusion-Inclusion Address Spaces' = $(
            if ($null -ne $ConfigurationData) {
              ${All Vlan Titles-Unsorted with Duplicates} = $ConfigurationData.AllNodes.Where({
                $null -ne $_.NodeMgmtCname
              }).'Network Refined v2'.'Adapters Config'.'VLAN Title'

              ${All Vlan Titles} = ${All Vlan Titles-Unsorted with Duplicates} | Sort-Object | Get-Unique

              #region | Credentials |
              $Target = "$NodeMgmtCname 544"
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion
              foreach (${Single Vlan Title} in ${All Vlan Titles}) {
                $IsVlanIdDefined = Test-Path -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                if ($IsVlanIdDefined) {
                  ${Vlan ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                  ${Vlan ID-Base10} = [System.Convert]::ToInt32(${Vlan ID-Binary},2)

                  $Resource_Title = "${Single Vlan Title} ${Vlan ID-Base10}" -replace '[^a-z0-9- _\.]','\'
                  $FilePath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\ExcIncOutline.clixml"
                  @{
                    Resource_Title       = $Resource_Title
                    FilePath             = $FilePath
                    Ensure               = 'Present'
                    PsDscRunAsCredential = $PsDscRunAsCredential
                  }
                }
              }
            }
          )
          'All Defined VLAN Titles' = $(
            if ($null -ne $ConfigurationData) {
              ${All Vlan Titles-Unsorted with Duplicates} = $ConfigurationData.AllNodes.Where({
                $null -ne $_.NodeMgmtCname
              }).'Network Refined v2'.'Adapters Config'.'VLAN Title'
              ${All Vlan Titles} = ${All Vlan Titles-Unsorted with Duplicates} | Sort-Object | Get-Unique
              ${All Vlan Titles}
            }
          )
          'Define Exclusion Address Spaces' = $(
            if ($null -ne $ConfigurationData) {
              $SelfRef = $(
                ${All Vlan Titles-Unsorted with Duplicates} = $ConfigurationData.AllNodes.Where({
                  $null -ne $_.NodeMgmtCname
                }).'Network Refined v2'.'Adapters Config'.'VLAN Title'

                ${All Vlan Titles} = ${All Vlan Titles-Unsorted with Duplicates} | Sort-Object | Get-Unique

                #region | Credentials |
                $Target = "$NodeMgmtCname 544"
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
              )
              foreach (${Single Vlan Title} in ${All Vlan Titles}) {
                $IsVlanIdDefined = Test-Path -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                if ($IsVlanIdDefined) {
                  ${Vlan ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                  ${Vlan ID-Base10} = [System.Convert]::ToInt32(${Vlan ID-Binary},2)

                  $Resource_Title = "${Single Vlan Title} ${Vlan ID-Base10}" -replace '[^a-z0-9- _\.]','\'
                  $OutputPath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\ExclusionSpace.clixml"
                  $InputPath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\ExcIncOutline.clixml"
                  $IsExclusionInclusionOutlineDefined = Test-Path -Path $InputPath
                  if ($IsExclusionInclusionOutlineDefined) {
                    @{
                      Resource_Title       = $Resource_Title
                      OutputPath           = $OutputPath
                      InputPath            = $InputPath
                      VLAN_ID_Binary       = ${Vlan ID-Binary}
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  }
                }
              }
            }
          )
          'Define Inclusion Address Spaces' = $(
            if ($null -ne $ConfigurationData) {
              $SelfRef = $(
                ${All Vlan Titles-Unsorted with Duplicates} = $ConfigurationData.AllNodes.Where({
                  $null -ne $_.NodeMgmtCname
                }).'Network Refined v2'.'Adapters Config'.'VLAN Title'

                ${All Vlan Titles} = ${All Vlan Titles-Unsorted with Duplicates} | Sort-Object | Get-Unique

                #region | Credentials |
                $Target = "$NodeMgmtCname 544"
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
              )
              foreach (${Single Vlan Title} in ${All Vlan Titles}) {
                $IsVlanIdDefined = Test-Path -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                if ($IsVlanIdDefined) {
                  ${Vlan ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                  ${Vlan ID-Base10} = [System.Convert]::ToInt32(${Vlan ID-Binary},2)

                  $Resource_Title = "${Single Vlan Title} ${Vlan ID-Base10}" -replace '[^a-z0-9- _\.]','\'
                  $OutputPath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\InclusionSpace.clixml"
                  $InputPath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\ExcIncOutline.clixml"
                  $IsExclusionInclusionOutlineDefined = Test-Path -Path $InputPath
                  if ($IsExclusionInclusionOutlineDefined) {
                    @{
                      Resource_Title       = $Resource_Title
                      OutputPath           = $OutputPath
                      InputPath            = $InputPath
                      VLAN_ID_Binary       = ${Vlan ID-Binary}
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  }
                }
              }
            }
          )
          'Define Exclusion Ranges Collection' = $(
            if ($null -ne $ConfigurationData) {
              $SelfRef = $(
                ${All Vlan Titles-Unsorted with Duplicates} = $ConfigurationData.AllNodes.Where({
                  $null -ne $_.NodeMgmtCname
                }).'Network Refined v2'.'Adapters Config'.'VLAN Title'

                ${All Vlan Titles} = ${All Vlan Titles-Unsorted with Duplicates} | Sort-Object | Get-Unique

                #region | Credentials |
                $Target = "$NodeMgmtCname 544"
                $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
              )
              foreach (${Single Vlan Title} in ${All Vlan Titles}) {
                $IsVlanIdDefined = Test-Path -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                if ($IsVlanIdDefined) {
                  ${Vlan ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${Single Vlan Title}.txt"
                  ${Vlan ID-Base10} = [System.Convert]::ToInt32(${Vlan ID-Binary},2)

                  $Resource_Title = "${Single Vlan Title} ${Vlan ID-Base10}" -replace '[^a-z0-9- _\.]','\'
                  $OutputPath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\ExclusionRangesDDN.clixml"
                  $InputPath = "$Statics\MaxIP\IPv4\${Single Vlan Title} $(${Vlan ID-Base10}.ToString('0000'))\ExcIncOutline.clixml"
                  $IsExclusionInclusionOutlineDefined = Test-Path -Path $InputPath
                  if ($IsExclusionInclusionOutlineDefined) {
                    @{
                      Resource_Title       = $Resource_Title
                      OutputPath           = $OutputPath
                      InputPath            = $InputPath
                      VLAN_ID_Binary       = ${Vlan ID-Binary}
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  }
                }
              }
            }
          )
          'Randomly Assign Unique IPv4 Addresses to Net IP Interfaces' = $(
            if ($null -ne $ConfigurationData) {
              ${Static or Dynamic IP Addresses of IPv4 Interfaces} = $ConfigurationData.AllNodes.Where({
                $null -ne $_.NodeMgmtCname
              }).'Network Refined v2'.'Adapters Config'.'All Settings on the IPv4 Interface bound to this Network Adapter'.'Static or Dynamic IP Address of IPv4 Interface'

              #region | Credentials |
              $Target = "$NodeMgmtCname 544"
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $Credential = [PSCredential]::New($un,$pw)

              $Target = "$NodeMgmtCname 544"
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion

              ${Randomly Assign Unique IPv4 Addresses to Net IP Interfaces} = ${Static or Dynamic IP Addresses of IPv4 Interfaces} | ForEach-Object -Process {
                $DestinationPath   = $_.IPAddressFilePath
                ${IP Address File} = [System.IO.FileInfo]$DestinationPath
            
                ${IP Address File}.Directory.Name -match '^(?<VLAN_Title>.+) (?<VLAN_ID_Base10_Padded>\d{4})$' | Out-Null
                $VLAN_Title = [System.String]$Matches['VLAN_Title']
                $VLAN_ID_Base10_Padded = [System.String]$Matches['VLAN_ID_Base10_Padded']

                #${IP Address File}.BaseName -match '^(?<Config_Target_Mgmt_Cname>[a-z0-9-]+) (?<Network_Adapter_Index>[0-9a-z]) (?<Adapter_Hardware_Type>.+)$' | Out-Null
                ${IP Address File}.BaseName -match '^(?<Config_Target_Mgmt_Cname>[a-z0-9-]+) (?<Network_Adapter_Index>[0-9a-z])$' | Out-Null
                $Config_Target_Mgmt_Cname = [System.String]$Matches['Config_Target_Mgmt_Cname']
                $Network_Adapter_Index = [System.String]$Matches['Network_Adapter_Index']
                $Adapter_Hardware_Type = [System.String]$Matches['Adapter_Hardware_Type']

                @{
                  #Resource_Title           =      "One-time generation of .txt file that holds IPv4 Address of the IP Interface with alias $VLAN_Title $Network_Adapter_Index $Adapter_Hardware_Type on $Config_Target_Mgmt_Cname"
                  Resource_Title            =      "One-time generation of .txt file that holds IPv4 Address of the IP Interface with alias $VLAN_Title $Network_Adapter_Index on $Config_Target_Mgmt_Cname"
                  DestinationPath           =      $DestinationPath
                  Attributes                =      @('ReadOnly')
                  Type                      =      'File'
                  Force                     =      $true
                  Ensure                    =      'Present'
                  Credential                =      $Credential
                  Dhcp                      =      $_.Dhcp
                  PsDscRunAsCredential      =      $PsDscRunAsCredential
                }
              }
              ${Randomly Assign Unique IPv4 Addresses to Net IP Interfaces}
            }
          )
          #endregion

          #region | "Non-System .vhdx File-System Objects with System account.ps1" |
          'Non-System VHD Files for All Hyper-V VMs' = $(
            if ($null -ne $ConfigurationData) {
              ${OS-level non-system disks-All VMs} = $ConfigurationData.AllNodes.Where({
                $_.Empire -eq 'VM'
              }).'OS-level non-system disks'

              foreach (${OS-level non-system disks} in ${OS-level non-system disks-All VMs}) {
                ${OS-level non-system disks}
              }
            }
          )
          #endregion

          #region | "One-time Write of VLAN Title and New Random VLAN ID with System account.ps1" |
          'VLAN .txt Files' = $(
            if ($null -ne $ConfigurationData) {
              ${All Vlan Titles-Unsorted with Duplicates} = $ConfigurationData.AllNodes.Where({
                $null -ne $_.NodeMgmtCname
              }).'Network Refined v2'.'Adapters Config'.'VLAN Title'

              ${All Vlan Titles} = ${All Vlan Titles-Unsorted with Duplicates} | Sort-Object | Get-Unique

              #region | Credentials |
              $Target = "$NodeMgmtCname 544"
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $Credential = [PSCredential]::New($un,$pw)

              $Target = "$NodeMgmtCname 544"
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion


              foreach (${Vlan Title} in ${All Vlan Titles}) {
                $DestinationPath = "$Statics\MaxIP\VLANs\${Vlan Title}.txt"
                $Resource_Title = "TXT file containing VLAN ID of the ${Vlan Title} VLAN" -replace '[^a-z0-9- _\.]','\'
                @{
                  Resource_Title       = $Resource_Title
                  DestinationPath      = $DestinationPath
                  Type                 = 'File'
                  Attributes           = @('ReadOnly')
                  #Contents            = $()
                  # One-time generation of random values with DSC v1.1 must take place in 
                  # Structural data and conditioned on the existence of a persistent entity,
                  # like a file-system object.
                  Force                = $true
                  Credential           = $Credential
                  Ensure               = 'Present'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              }
            }
          )
          #endregion
          #region | "One-time Write of VM Switch UUID with System account.ps1" |
          'VM Switch UUID .txt Files' = $(
            if ($null -ne $ConfigurationData) {
              #region | Credentials |
              $Target = "$NodeMgmtCname 544"
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $Credential = [PSCredential]::New($un,$pw)

              $Target = "$NodeMgmtCname 544"
              $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
              $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion

              ${Environmental Data of All Hyper-V Hosts} = $ConfigurationData.AllNodes.Where({$_.Dominion -eq 'Hyper-V'})
              ${All Virtual Switch Key Titles} = ${Environmental Data of All Hyper-V Hosts} `
              | Select-Object -ExpandProperty 'Keys' `
              | Where-Object -FilterScript {
                $_ -match '^Virtual Switch Clade \d\d---'
              }

              foreach (${EnvData of HvH} in ${Environmental Data of All Hyper-V Hosts}) {
                foreach (${Virtual Switch Key Title} in ${All Virtual Switch Key Titles}) {
                  if (
                    $null -ne ${EnvData of HvH}.${Virtual Switch Key Title}
                  ) {
                    ${vSwitch UUID .txt File BaseName} = ${EnvData of HvH}.${Virtual Switch Key Title}.Resource_Title -replace '\\','_'
                    $Resource_Title = ${EnvData of HvH}.${Virtual Switch Key Title}.Resource_Title
                    #${vSwitch UUID .txt File FullName} = "$Statics\vHW\sw\$Resource_Title.txt"
                    ${vSwitch UUID .txt File FullName} = "$Statics\vHW\sw\${vSwitch UUID .txt File BaseName}.txt"
                    @{
                      Resource_Title       = $Resource_Title
                      DestinationPath      = ${vSwitch UUID .txt File FullName}
                      Type                 = 'File'
