                ${CER File Collection of Client Authentication certs for Mutual Authentication} = $ConfigurationData.AllNodes.Where({
                  $_.NodeMgmtCname -eq ${Configuration Target Mgmt Cname}
                }).'CER File Collection of Client Authentication certs for Mutual Authentication'

                if ($null -ne ${CER File Collection of Client Authentication certs for Mutual Authentication}) {
                  foreach (${CER File of Client Authentication cert for Mutual Authentication} in ${CER File Collection of Client Authentication certs for Mutual Authentication}) {
                    @{
                      Resource_Title       = ${CER File of Client Authentication cert for Mutual Authentication}.Resource_Title
                      FriendlyName         = ${CER File of Client Authentication cert for Mutual Authentication}.FriendlyName
                      Ensure               = ${CER File of Client Authentication cert for Mutual Authentication}.Ensure
                      PsDscRunAsCredential = ${CER File of Client Authentication cert for Mutual Authentication}.PsDscRunAsCredential
                    }
                  }
                }
              }
            }
          )

          'PFX Files of Document Encryption certs for MOF Password Protection' = $(
            if ($null -ne $ConfigurationData) {
              $ConfigurationData.AllNodes.Where({
                $null -ne $_.NodeMgmtCname
              }).'PFX File of Document Encryption cert for MOF Password Protection'
            }
          )
          'PFX Files of Document Encryption certs for Event Log Privacy' = $(
            if ($null -ne $ConfigurationData) {
              $ConfigurationData.AllNodes.Where({
                $null -ne $_.NodeMgmtCname
              }).'PFX File of Document Encryption cert for Event Log Privacy'
            }
          )
          'PFX Files of Server Authentication certs for Mutual Authentication' = $(
