                  #Good Stuff#$_.UserName -eq "$AD_NetBIOS 580" -or `
                  #Good Stuff#$_.UserName -eq "$AD_NetBIOS 544" -or `
                  #Good Stuff#$_.UserName -eq "$AD_NetBIOS 220"
                })

                #region | Credentials |
                $PsDscUn = [QuickMgmtCnameConversion]::Un($NodeMgmtCname)
                $HT = @{Target = $PsDscUn; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $PsDscPw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($PsDscUn,$PsDscPw)
                #endregion
                #endregion
                foreach ($acct in ${DISABLED Local User Accounts}) {
                  $UserName = $acct.UserName
                  $Resource_Title = "Local User Account $UserName" -replace '[^\w\d-\\ \.]','\\'
                  @{
                    Resource_Title           = $Resource_Title
                    UserName                 = $UserName
                    FullName                 = $UserName
                    Password                 = $acct.Password
                    Description              = $acct.Description
                    Disabled                 = -not $acct.Enabled
                    PasswordChangeNotAllowed = $acct.CannotChangePassword
                    PasswordChangeRequired   = $acct.ChangePasswordAtLogon
