                    Ensure                   = $acct.Ensure
                    PsDscRunAsCredential     = $PsDscRunAsCredential
                  }
                }
              }
            }
          )
          'Local Groups' = $(
            #region | Credentials |
            $PsDscUn = "DC OS Deploy"
            $HT = @{Target = $PsDscUn; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $PsDscPw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Credential = [PSCredential]::New($PsDscUn,$PsDscPw)
            #if ($null -ne $PsDscPw) {$Credential = [PSCredential]::New($PsDscUn,$PsDscPw)}
            $PsDscRunAsCredential = [PSCredential]::New($PsDscUn,$PsDscPw)
            #if ($null -ne $PsDscPw) {$PsDscRunAsCredential = [PSCredential]::New($PsDscUn,$PsDscPw)}
            #endregion
            @(
              @{ # Administrators |
                Reference = $(
                  $GroupName = 'Administrators'
                  #$Description = (Get-LocalGroup -Name $GroupName).Description # plain-text is faster
                  $Description = 'Administrators have complete and unrestricted access to the computer/domain'
                  $MembersToInclude = @(
                    "$AD_NetBIOS 544"
                    "$AD_NetBIOS 220"
                    "DC_LocalAdmin"
                    $(
                      $UpnPrefix = 'Domain Controller Local Admin 0'
                      $UpnSuffix = ${Upn Suffix Gamma}
                      $UserPrincipalName = "$UpnPrefix@$UpnSuffix"
                      [p2k]::un($UserPrincipalName)
                    )
                    $(
                      $UpnPrefix = 'Domain Controller Local Admin 1'
                      $UpnSuffix = ${Upn Suffix Gamma}
                      $UserPrincipalName = "$UpnPrefix@$UpnSuffix"
                      [p2k]::un($UserPrincipalName)
                    )
                  )
                )
                Resource_Title       = "Local Group $GroupName"
                GroupName            = $GroupName
                Description          = $Description
                MembersToInclude     = $MembersToInclude
                Credential           = $Credential
                Ensure               = 'Present'
                PsDscRunAsCredential = $PsDscRunAsCredential
              }
              @{ # Remote Management Users |
                Reference = $(
                  $GroupName = 'Remote Management Users'
                  #$Description = (Get-LocalGroup -Name $GroupName).Description # plain-text is faster
                  $Description = 'Members of this group can access WMI resources over management protocols (such as WS-Management via the Windows Remote Management service). This applies only to WMI namespaces that grant access to the user.'
                  $MembersToInclude = @(
                    $(
