            $UpnPrefix = "$AD_NetBIOS 500"
            $UpnSuffix = $AD_DNS
            $UserPrincipalName = "$UpnPrefix@$UpnSuffix"
            $UserName = 'Administrator'
            $HT = @{Target = $UserPrincipalName; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Password = [PSCredential]::New($UserName,$pw)

            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            @{
              Resource_Title           = "Built-In Administrator Acct on $NodeMgmtCname"
              UserName                 = $UserName
              FullName                 = "Built-in local Administrator on $NodeMgmtCname"
              Password                 = $Password
              Description              = "Built-in account for administering the computer/domain"
              Disabled                 = $false
              PasswordChangeNotAllowed = $false
              PasswordChangeRequired   = $false
              PasswordNeverExpires     = $true
              Ensure                   = 'Present'
              PsDscRunAsCredential     = $PsDscRunAsCredential
            }
          )
          #endregion
          #region | "Environment Variable Definitions with System account.ps1" |
          # Also see GCD node in $ConfigurationData
          'Environment Variable Definitions Credential' = $(
            #region |  |
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #endregion
            @{
              PsDscRunAsCredential = $PsDscRunAsCredential
            }
          )  
          #endregion
          #region | "Directory Structure inside DSC_CFG_ROOT with System account.ps1" |
          'DSC_CFG_ROOT Directory Tree Credentials' = $(
            #region |  |
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Credential = [PSCredential]::New($un,$pw)

            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
