            #endregion
            #endregion
            @{
              Credential           = $Credential
              PsDscRunAsCredential = $PsDscRunAsCredential
            }
          )
          #endregion
          #region | "WinRM Part 1-WS-Man Client Config, WinRM Windows Service, WS-Man Service Settings with System account.ps1" | "WinRM Part 2-HTTPS-Protected PowerShell Remoting with System account.ps1" |
          'Web Services Management' = $(
            @{
              'WS-Man Client Config' = $(
                #region |  |
                #region | Credentials |
                $un = "$AD_NetBIOS 544"
                $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                #endregion
                @{
                  Resource_Title       = "Max Envelope Size on $NodeMgmtCname"
                  IsSingleInstance     = 'Yes'
                  MaxEnvelopeSizekb    = ${WSMan MaxEnvelopeSizeKb}
                  MaxTimeoutms         = 120000 # 180000 milliseconds is 3 minutes
                  MaxBatchItems        = 64000
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              'WS-Man Listeners' = $(
                @{
                  'WS-Management HTTPS Listener' = $(
                    #region |  |
                    ${Thumbprint of Server Authentication certificate installed on client attempting PowerShell Remoting connection into this server} = $(
                      Get-ChildItem -Path "Cert:\LocalMachine\My" | Where-Object -FilterScript {
                        $_.FriendlyName -eq "WS-Man Connection Into $NodeMgmtCname"
                      } | Select-Object -ExpandProperty 'Thumbprint'
                    )
                    #region | Credentials |
                    $un = "$AD_NetBIOS 544"
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                    $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                    #endregion
                    #endregion
                    @{
                      Resource_Title        = "HTTPS Listener_$($NodeMgmtCname)_Pre-PKI"
                      Transport             = 'HTTPS'
                      CertificateThumbprint = ${Thumbprint of Server Authentication certificate installed on client attempting PowerShell Remoting connection into this server}
                      Address               = '*'
                      Ensure                = 'Present'
                      PsDscRunAsCredential  = $PsDscRunAsCredential
                    }
                  )
                  'WS-Management HTTP Listener' = $(
                    #region |  |
                    #region | Credentials |
                    $un = "$AD_NetBIOS 544"
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                    $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                    #endregion
                    #endregion
                    @{
                      Resource_Title       = "HTTP Listener_$($NodeMgmtCname)_Pre-PKI"
                      Transport            = 'HTTP'
                      Address              = '*'
                      Ensure               = 'Defined in configuration document'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                }
              )
              'WS-Man Service settings' = $(
                #region |  |
                #region | Credentials |
