                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                  VMHardDiskDrive = $(
                    @{
                      Resource_Title       = "${Vhdx File BaseName} on $NodeMgmtCname"
                      Path                 = "${env:VHD Folder Path}\${Vhdx File BaseName}.vhdx"
                      VMName               = [QuickMgmtCnameConversion]::VM($NodeMgmtCname)
                      ControllerNumber     = ${Controller Index}
                      ControllerLocation   = [System.Int32]${Location Index Padded}
                      ControllerType       = 'SCSI'
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                }
              )
              $(${Controller Index} = '2'; ${Location Index} = 0;
                #region | |
                ${Location Index Padded} = (${Location Index}).ToString('00')
                ${Vhdx File BaseName} = "$($VmOrdinal) Ctrl ${Controller Index} Loc ${Location Index Padded}"
                ${Storage Resiliency Reference} = ${Storage Spaces Virtual Disk-Neon}
                #endregion
                @{
                  'Storage Resiliency Reference' = ${Storage Resiliency Reference}
                  VirtualHardDisk = $(
                    @{
                      Resource_Title       = $NodeMgmtCname + ' ' + ${Vhdx File BaseName}
                      FilePath             = "$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 2-Unique\$NodeMgmtCname\${Vhdx File BaseName}.vhdx"
                      DiskFormat           = 'vhdx'
                      DiskSize             = 256GB
                      DiskType             = 'Dynamic'
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                  'Text File with UniqueId' = $(
                    @{
                      Resource_Title       = "UniqueId for ${Vhdx File BaseName} on $NodeMgmtCname"
                      DestinationPath      = "$Statics\VHDs\$NodeMgmtCname\${Vhdx File BaseName}.txt"
                      Type                 = 'File'
                      Attributes           = @('ReadOnly')
                      Contents             = "Value for UniqueId resolved in structural data"
                      Checksum             = 'SHA-256'
                      Force                = $false
                      MatchSource          = $false
                      Recurse              = $false
                      Credential           = $Credential
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                  'VHDX File' = $(
                    @{
                      Resource_Title       = "VHDX File ${Vhdx File BaseName} on $NodeMgmtCname"
                      DestinationPath      = "${env:VHD Folder Path}\${Vhdx File BaseName}.vhdx"
                      SourcePath           = "$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 2-Unique\$NodeMgmtCname\${Vhdx File BaseName}.vhdx"
                      Type                 = 'File'
                      Attributes           = @()
                      Credential           = $Credential
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                  VMHardDiskDrive = $(
                    @{
                      Resource_Title       = "${Vhdx File BaseName} on $NodeMgmtCname"
                      Path                 = "${env:VHD Folder Path}\${Vhdx File BaseName}.vhdx"
                      VMName               = [QuickMgmtCnameConversion]::VM($NodeMgmtCname)
                      ControllerNumber     = ${Controller Index}
                      ControllerLocation   = [System.Int32]${Location Index Padded}
                      ControllerType       = 'SCSI'
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                }
              )
            )
          )
          'Virtual Disk Structure' = $(
            #region |  |
            $ResiliencySettingName   = 'Parity'
            $StoragePoolFriendlyName = 'Storage Pool'
            $ProvisioningType        = 'Thin'
            $Size                    = 128GB
            #endregion
            @(
              $($FriendlyName = [StoragePoolVirtualDiskFriendlyName]::Helium; ${Volume Letter} = $($advol -replace ':',''); ${Volume Label} = "Active Directory";
                @{
                  FriendlyName            = $FriendlyName
                  ResiliencySettingName   = $ResiliencySettingName
                  StoragePoolFriendlyName = $StoragePoolFriendlyName
                  ProvisioningType        = $ProvisioningType
                  Size                    = $Size
                  'Volume Letter'         = ${Volume Letter}
                  'Volume Label'          = ${Volume Label}
                }
              )
              $($FriendlyName = [StoragePoolVirtualDiskFriendlyName]::Neon; ${Volume Letter} = "K"; ${Volume Label} = "Apps-00";
                @{
                  FriendlyName            = $FriendlyName
                  ResiliencySettingName   = $ResiliencySettingName
                  StoragePoolFriendlyName = $StoragePoolFriendlyName
                  ProvisioningType        = $ProvisioningType
                  Size                    = $Size
                  'Volume Letter'         = ${Volume Letter}
                  'Volume Label'          = ${Volume Label}
                }
              )
              $($FriendlyName = [StoragePoolVirtualDiskFriendlyName]::Argon; ${Volume Letter} = "L"; ${Volume Label} = "Backup-AD";
                @{
                  FriendlyName            = $FriendlyName
                  ResiliencySettingName   = $ResiliencySettingName
                  StoragePoolFriendlyName = $StoragePoolFriendlyName
                  ProvisioningType        = $ProvisioningType
                  Size                    = $Size
                  'Volume Letter'         = ${Volume Letter}
                  'Volume Label'          = ${Volume Label}
                }
              )
            )
          )
          #endregion
          'Hyper-V Virtual Machine' = $(${Virtual Switch Name} = 'SET-enabled External vSwitch'; [System.UInt16]${Memory Divisor} = 8; $vCpuQty = 2; $StartupMemoryScale = 1.00; 
            #region |  |
            [QuickMgmtCnameConversion]::VM($NodeMgmtCname) -match '^(?<Ordinal>\d\d\.\d\d)\s(?<Colloquial>.+)$' | Out-Null
            $VmOrdinal = $Matches['Ordinal']
            $VmColloquial = $Matches['Colloquial']
            ${System Disk File} = [System.IO.FileInfo]"${env:VHD Folder Path}\$VmOrdinal Ctrl 0 Loc 00~$VmColloquial.vhdx"

            # Default quantity of RAM assigned to the VM is 1/${Memory Divisor} total physical RAM, so install the maximum amount on your Hyper-V hosts!
            ${Total Memory Capacity on Hyper-V Host as Double} = Get-CimInstance -ClassName 'Win32_PhysicalMemory' | Select-Object -ExpandProperty 'Capacity' | Measure-Object -Sum | Select-Object -ExpandProperty 'Sum'
            ${Total Memory Capacity on Hyper-V Host as UInt64} = [System.UInt64]${Total Memory Capacity on Hyper-V Host as Double}
            $MaximumMemory = 1MB * [System.Math]::Round((${Total Memory Capacity on Hyper-V Host as UInt64}/(${Memory Divisor} * 1024 * 1024)),0)
            $StartupMemory = [System.Math]::Round($StartupMemoryScale * $MaximumMemory,0)

            #region | Credentials | NOTE: This key-value pair is fed into the config target providing the Hyper-V host. As such, $Target = "${DSC Authoring Station Mgmt Cname} 544" |
            $Target = ${DSC Authoring Station Mgmt Cname} + ' ' + 544
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $un = [QuickMgmtCnameConversion]::CN(${DSC Authoring Station Mgmt Cname}) + ' ' + 544
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #endregion
            @{
              Resource_Title              = "Hyper-V Virtual Machine $NodeMgmtCname"
              Name                        = [QuickMgmtCnameConversion]::VM($NodeMgmtCname)
              VhdPath                     = ${System Disk File}.FullName
              State                       = 'Running'
              AutomaticCheckpointsEnabled = $true
              EnableGuestService          = $true
              Generation                  = 2
              #MACAddress                 = Leave omitted. Original vNIC gets deleted in our workflow. 
              MaximumMemory               = $MaximumMemory
              MinimumMemory               = 256MB
              StartupMemory               = $StartupMemory
              Notes                       = [QuickMgmtCnameConversion]::VMNotes($NodeMgmtCname)
              Path                        = ${env:VM Folder Path}
              ProcessorCount              = $vCpuQty
              RestartIfNeeded             = $true
              WaitForIP                   = $false
              SecureBoot                  = $true
              SwitchName                  = ${Virtual Switch Name}
              Ensure                      = 'Present'
              PsDscRunAsCredential        = $PsDscRunAsCredential
            }
          )
          'vCPU in Virtual Machine' = $(
            #region | Credentials | NOTE: This key-value pair is fed into the config target providing the Hyper-V host. As such, $Target = "${DSC Authoring Station Mgmt Cname} 544" |
            $Target = ${DSC Authoring Station Mgmt Cname} + ' ' + 544
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $un = [QuickMgmtCnameConversion]::CN(${DSC Authoring Station Mgmt Cname}) + ' ' + 544
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            @{
              Resource_Title                               = "vCPU $NodeMgmtCname"
              VMName                                       = [QuickMgmtCnameConversion]::VM($NodeMgmtCname) 
              CompatibilityForMigrationEnabled             = $false
              CompatibilityForOlderOperatingSystemsEnabled = $false
              EnableHostResourceProtection                 = $false
              ExposeVirtualizationExtensions               = $false
              HwThreadCountPerCore                         = 1
              Maximum                                      = 100
              MaximumCountPerNumaNode                      = 24
              MaximumCountPerNumaSocket                    = 1
              RelativeWeight                               = 100
              Reserve                                      = 0
              ResourcePoolName                             = 'Primordial'
              RestartIfNeeded                              = $true
              PsDscRunAsCredential                         = $PsDscRunAsCredential
            }
          )
          'Hyper-V Virtual Network Adapter Definitions' = $(
            if ($null -ne $ConfigurationData) {
              ${Adapters Config on Config Target Node VM} = $ConfigurationData.AllNodes.Where({
                $_.NodeMgmtCname -eq $NodeMgmtCname
              }).'Network Refined v2'.'Adapters Config'

              if ($null -ne ${Adapters Config on Config Target Node VM}) {
                #region | Credentials | NOTE: This key-value pair is fed into the config target providing the Hyper-V host. As such, $Target = "${DSC Authoring Station Mgmt Cname} 544" |
                $Target = ${DSC Authoring Station Mgmt Cname} + ' ' + 544
                $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $un = [QuickMgmtCnameConversion]::CN(${DSC Authoring Station Mgmt Cname}) + ' ' + 544
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                ${Hyper-V Virtual Network Adapter Definitions on Instance} = foreach (${Adapter Config on Config Target Node VM} in ${Adapters Config on Config Target Node VM}) {
                  #region |  |
                  ${Title of Connected VLAN} = ${Adapter Config on Config Target Node VM}.'VLAN Title'
                  ${vlanid in Base10 without leading Zeroes} = [System.Int32]${Adapter Config on Config Target Node VM}.'VLAN ID-Base10'
                  ${Layer 2 Address} = ${Adapter Config on Config Target Node VM}.'MAC Address Raw'
                  ${Address Info on IPv4 Net IP Interface} = ${Adapter Config on Config Target Node VM}.'All Settings on the IPv4 Interface bound to this Network Adapter'.'Static or Dynamic IP Address of IPv4 Interface'
                  ${State of DHCPv4 Client on Net IP Interface} = ${Address Info on IPv4 Net IP Interface}.Dhcp
                  ${Layer 3 Address of IPv4 Net IP Interface-DDN} = ${Address Info on IPv4 Net IP Interface}.IPAddress -replace '/22',''
                  ${Layer 3 Address of IPv4 Default Gateway-DDN} = ${Adapter Config on Config Target Node VM}.'All Settings on the IPv4 Interface bound to this Network Adapter'.'IP Address of Default Gateway on Static IPv4 Interface'.Address
                  if (${Layer 3 Address of IPv4 Net IP Interface-DDN}.Length -ne 0) {
                    ${32-bit Subnet Mask-DDN} = Get-NetworkSummary ${Address Info on IPv4 Net IP Interface}.IPAddress -ErrorAction 'SilentlyContinue' | Select-Object -ExpandProperty 'Mask' | Select-Object -ExpandProperty 'IPAddressToString'
                  }
                  ${Destination IPv4 Address for DNS queries emitted from this Net IP Interface-DDN} = ${Adapter Config on Config Target Node VM}.'All Settings on the IPv4 Interface bound to this Network Adapter'.'IP Address of DNS Server on Static IPv4 Interface'.Address

                  ${Layer 3 IPv4 Address File Path} = ${Address Info on IPv4 Net IP Interface}.IPAddressFilePath
                  ${Layer 3 IPv4 Address File} = [System.IO.FileInfo]${Layer 3 IPv4 Address File Path}
                  ${Layer 3 IPv4 Address File}.BaseName -match '^(?<Config_Target_Mgmt_Cname>[a-z0-9-]+) (?<NetAdapter_Index>[0-9a-z])$' | Out-Null
                  $NetAdapter_Index = [System.Char]$Matches['NetAdapter_Index']

                  ${ID to Distinguish VMNetworkAdapter} = ${Adapter Config on Config Target Node VM}.'Net Adapter Name'.Resource_Title
                  ${Name of VMNetworkAdapter} = ${Adapter Config on Config Target Node VM}.'Net Adapter Name'.NewName
                  ${Connected vSwitch Name} = ${Adapter Config on Config Target Node VM}.'Connected vSwitch Name'
                  ${Title of Hyper-V Virtual Machine to which this Net Adapter is Bound} = [QuickMgmtCnameConversion]::VM($NodeMgmtCname)
                  #endregion
                  ${Environmental Data Consumed by an Instance of the VMNetworkAdapter DSC Resource provided by HyperVDsc} = $(
                    switch (${State of DHCPv4 Client on Net IP Interface}) {
                      'Enabled' {
                        $Resource_Title = "VMNetworkAdapter $NetAdapter_Index connected to ${Title of Connected VLAN} on the $NodeMgmtCname VM" -replace '[^\w\d-\\ \.]','\\'
                        @{
                          Resource_Title       = $Resource_Title
                          Id                   = ${ID to Distinguish VMNetworkAdapter}
                          Name                 = ${Name of VMNetworkAdapter}
                          SwitchName           = ${Connected vSwitch Name}
                          VMName               = ${Title of Hyper-V Virtual Machine to which this Net Adapter is Bound}
                          MacAddress           = ${Layer 2 Address}
                          VlanId               = ${vlanid in Base10 without leading Zeroes}
                          Ensure               = 'Present'
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      }
                      'Disabled' {
                        $Resource_Title = "VMNetworkAdapter $NetAdapter_Index connected to ${Title of Connected VLAN} on the $NodeMgmtCname VM" -replace '[^\w\d-\\ \.]','\\'
                        @{
                          Resource_Title       = $Resource_Title
                          Id                   = ${ID to Distinguish VMNetworkAdapter}
                          Name                 = ${Name of VMNetworkAdapter}
                          SwitchName           = ${Connected vSwitch Name}
                          VMName               = ${Title of Hyper-V Virtual Machine to which this Net Adapter is Bound}
                          MacAddress           = ${Layer 2 Address}
                          NetworkSetting       = $(
                            @{
                              Subnet         = ${32-bit Subnet Mask-DDN}
                              DefaultGateway = ${Layer 3 Address of IPv4 Default Gateway-DDN}
                              DnsServer      = ${Destination IPv4 Address for DNS queries emitted from this Net IP Interface-DDN}
                              IpAddress      = ${Layer 3 Address of IPv4 Net IP Interface-DDN}
                            }
                          )
                          VlanId               = ${vlanid in Base10 without leading Zeroes}
                          Ensure               = 'Present'
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      }
                    }
                  )
                  ${Environmental Data Consumed by an Instance of the cVMNetworkAdapterSettings DSC Resource provided by cHyper-V} = $(
                    $Resource_Title = "Settings for VMNetworkAdapter $NetAdapter_Index connected to ${Title of Connected VLAN} on the $NodeMgmtCname VM" -replace '[^\w\d-\\ \.]','\\'
                    @{
                      Resource_Title             =   $Resource_Title
                      Id                         =   ${ID to Distinguish VMNetworkAdapter}
                      Name                       =   ${Name of VMNetworkAdapter}
                      SwitchName                 =   ${Connected vSwitch Name}
                      VMName                     =   ${Title of Hyper-V Virtual Machine to which this Net Adapter is Bound}
                      AllowTeaming               =   'Off'
                      DeviceNaming               =   'On' # NetAdapterRename will handle os-level renaming
                      DhcpGuard                  =   'On'
                      IeeePriorityTag            =   'On'
                      MacAddressSpoofing         =   'Off'
                      #MaximumBandwidth          =   ""
                      #MinimumBandwidthAbsolute  =   ""
                      #MinimumBandwidthWeight    =   ""
                      PortMirroring              =   'None'
                      RouterGuard                =   'On'
                      #VmqWeight                 =   ""
                      PsDscRunAsCredential       =   $PsDscRunAsCredential
                    }
                  )
                  ${Environmental Data Consumed by an Instance of the cVMNetworkAdapterVlan DSC Resource provided by cHyper-V} = $(
                    $Resource_Title = "Settings for VMNetworkAdapter $NetAdapter_Index connected to ${Title of Connected VLAN} on the $NodeMgmtCname VM" -replace '[^\w\d-\\ \.]','\\'
                    @{
                      Resource_Title       = $Resource_Title
                      Id                   = ${ID to Distinguish VMNetworkAdapter}
                      Name                 = ${Name of VMNetworkAdapter}
                      VMName               = ${Connected vSwitch Name}
                      AdapterMode          = 'Access'
                      AllowedVlanIdList    = ""
                      NativeVlanId         = ""
                      PrimaryVlanId        = ""
                      SecondaryVlanId      = ""
                      SecondaryVlanIdList  = ""
                      VlanId               = ${vlanid in Base10 without leading Zeroes}
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                  @{
                    'State of DHCPv4 Client on Net IP Interface' = ${State of DHCPv4 Client on Net IP Interface}
                    VMNetworkAdapter                             = ${Environmental Data Consumed by an Instance of the VMNetworkAdapter DSC Resource provided by HyperVDsc}
                    cVMNetworkAdapterSettings                    = ${Environmental Data Consumed by an Instance of the cVMNetworkAdapterSettings DSC Resource provided by cHyper-V}
                    cVMNetworkAdapterVlan                        = ${Environmental Data Consumed by an Instance of the cVMNetworkAdapterVlan DSC Resource provided by cHyper-V}
                  }
                }

                foreach (${Hyper-V Virtual Network Adapter Definition} in ${Hyper-V Virtual Network Adapter Definitions on Instance}) {
                  @{
                    'State of DHCPv4 Client on Net IP Interface' = ${Hyper-V Virtual Network Adapter Definition}.'State of DHCPv4 Client on Net IP Interface'
                    VMNetworkAdapter                             = ${Hyper-V Virtual Network Adapter Definition}.VMNetworkAdapter
                    cVMNetworkAdapterSettings                    = ${Hyper-V Virtual Network Adapter Definition}.cVMNetworkAdapterSettings
                    cVMNetworkAdapterVlan                        = ${Hyper-V Virtual Network Adapter Definition}.cVMNetworkAdapterVlan
                  }
                }
              }
            }
          )
          #endregion
          #region | "Firewall-Allow Inbound HTTPS-secured WinRM with System account.ps1" |
          'Firewall-Allow Inbound HTTPS-secured WinRM' = $(
            #region |  |
            $Name = 'Windows Remote Management (HTTPS-In)'
            $DisplayName = 'Windows Remote Management (HTTPS-In)'
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #endregion
            @{
              Resource_Title         = $Name -replace '[^a-z0-9- _\.]','\'
              Name                   = $Name
              DisplayName            = $DisplayName
              Group                  = 'Windows Remote Management'
              Description            = "Local inbound rule for WinRM via WS-Man (TCP 5986) that demonstrates an HTTPS-secured PowerShell Remoting connection into $NodeMgmtCname."
              Enabled                = 'True'
              Action                 = 'Allow'
              Direction              = 'Inbound'
              Protocol               = 'TCP'
              LocalPort              = ('5986')
              # Service              = 'WinRM'
              RemoteAddress          = ('Any')
              # Authentication       = 'Required' # 'NoEncap','NotRequired'
              # Encryption           = 'Required' # 'Dynamic','NotRequired','Required'
              Profile                = ('Domain','Private','Public')
              # DynamicTransport     = [System.String]{ Any | ProximityApps | ProximitySharing | WifiDirectDevices | WifiDirectDisplay | WifiDirectPrinting }
              # EdgeTraversalPolicy  = [System.String]{ Allow | Block | DeferToApp | DeferToUser }
              # IcmpType             = [System.String[]]
              # InterfaceAlias       = [System.String[]]
              # InterfaceType        = [System.String]{ Any | RemoteAccess | Wired | Wireless }
              # LocalAddress         = [System.String[]]
              # LocalOnlyMapping     = [System.Boolean]
              # LocalUser            = [System.String]
              # LooseSourceMapping   = [System.Boolean]
              # OverrideBlockRules   = [System.Boolean]
              # Owner                = [System.String]
              # Package              = [System.String]
              # Platform             = [System.String[]]
              # Program              = [System.String]
              # RemoteMachine        = [System.String]
              # RemotePort           = [System.String[]]
              # RemoteUser           = [System.String]
              Ensure                 = 'Present'
              PsDscRunAsCredential   = $PsDscRunAsCredential
            }
          )
          #endregion
          #region | "Permissions Entries of WMI Namespaces on Remote Machines with System account.ps1" |
          'WMI Namespace Access Right Set Collection' = $(
            #region |  |
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #endregion
            @(
              $( # Remote Management Users-Read DSCproxy |
                @{
                  Resource_Title       = 'Remote Management Users-Read DSCproxy'
                  AccountName          = '.\Remote Management Users'
                  <#
                    ACL = @(
                      cim_acl {
                        AceFlags = 'NameSpaceOnly'          # ChildOnly # WithChild
                        Allow    = $true
                        right    = 'Enable','MethodExecute','ProviderWrite','RemoteAccess' # 'FullWrite','PartialWrite','Subscribe','Publish','ReadSecurity','WriteSecurity'
                      }
                    )
                  #>
                  NameSpace            = 'root\Microsoft\Windows\DesiredStateConfigurationProxy'
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
            )
          )
          #endregion
          #region | "Update ComputerName with System account.ps1" "Reboot after ComputerName Update with System account.ps1" |
          '%ComputerName% Update' = $(
            $NodeComputerName = Get-Content -ErrorAction 'SilentlyContinue' -Path "$Statics\CNs\$NodeMgmtCname ComputerName.txt"
            #region |  |
            ${User Name} = $([QuickMgmtCnameConversion]::Un($NodeMgmtCname))
            $HT = @{Target = ${User Name}; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Credential = [PSCredential]::New(${User Name},$pw)

            ${User Name} = $([QuickMgmtCnameConversion]::Un($NodeMgmtCname))
            $HT = @{Target = ${User Name}; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New(${User Name},$pw)
            #endregion
            @{
              Resource_Title       = "Update system $NodeMgmtCname with randomly generated ComputerName"
              Name                 = $NodeComputerName
              Description          = [QuickMgmtCnameConversion]::ComputerDescriptionBeforeDomainJoin($NodeMgmtCname)
              Credential           = $Credential
              PsDscRunAsCredential = $PsDscRunAsCredential
            }
          )
          'Reboot After Updating %ComputerName%' = $(
            #region |  |
            ${User Name} = $([QuickMgmtCnameConversion]::Un($NodeMgmtCname))
            $HT = @{Target = ${User Name}; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New(${User Name},$pw)
            #endregion
            @{
              Resource_Title              = "Hostname change on $NodeMgmtCname leads to Pending Reboot"
              Name                        = "PendingComputerRename"
              SkipPendingComputerRename   = $false
              SkipCcmClientSDK            = $false # Must be false for domain-join to prompt a reboot
              SkipComponentBasedServicing = $false
              SkipPendingFileRename       = $false
              SkipWindowsUpdate           = $false # do we want to skip reboots resulting from new Windows Updates?
              PsDscRunAsCredential        = $PsDscRunAsCredential
            }
          )
          #endregion
          #region | Space Saver (Temporary) |
          #region | "Pre-PKI Cert Imports with System account.ps1" and "Accumulated System VHDX Cascades with System account.ps1" on Unclustered Hyper-V Host |
          'Import Pre-PKI Global Certificate Signer' = $(
            #region |  |
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            $FriendlyName = 'Pre-PKI Global Certificate Signer'
            ${.cer File FullName} = "${env:Pre-PKI CertFSOs}\$FriendlyName.cer"
            $Resource_Title = $FriendlyName -replace '[^\w\d-\\ \.]','\\'

            ${Thumbprint File Path} = "${env:Pre-PKI CertFSOs}\$FriendlyName.txt"
            if (Test-Path -Path ${Thumbprint File Path}) {
              $Thumbprint = Get-Content -Path "${env:Pre-PKI CertFSOs}\$FriendlyName.txt"
              @{
                Resource_Title       = $Resource_Title
                Location             = 'LocalMachine'
                Store                = 'Root'
                Thumbprint           = $Thumbprint
                FriendlyName         = $FriendlyName
                Path                 = ${.cer File FullName}
                Ensure               = 'Present'
                PsDscRunAsCredential = $PsDscRunAsCredential
              }
            }
            #endregion
          )
          'Import Pre-PKI Global Code Signer' = $(
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            $FriendlyName = 'Pre-PKI Global Code Signer'
            ${.cer File FullName} = "${env:Pre-PKI CertFSOs}\$FriendlyName.cer"
            $Resource_Title = $FriendlyName -replace '[^\w\d-\\ \.]','\\'

            ${Thumbprint File Path} = "${env:Pre-PKI CertFSOs}\$FriendlyName.txt"
            if (Test-Path -Path ${Thumbprint File Path}) {
              $Thumbprint = Get-Content -Path "${env:Pre-PKI CertFSOs}\$FriendlyName.txt"
              @{
                Resource_Title       = $Resource_Title
                Location             = 'LocalMachine'
                Store                = 'My'
                Thumbprint           = $Thumbprint
                FriendlyName         = $FriendlyName
                Path                 = ${.cer File FullName}
                Ensure               = 'Present'
                PsDscRunAsCredential = $PsDscRunAsCredential
              }
            }
          )
          'Import Pre-PKI Server Authentication CER Files' = $(
            if ($null -ne $ConfigurationData) {
              #region | Credentials |
              $un = "$AD_NetBIOS 544"
              $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion

              ${Mgmt Cnames of Net IP Interfaces of ALL OTHER WinRM Remoting Targets} = $ConfigurationData.AllNodes.Where({
                $_.NodeMgmtCname -ne $NodeMgmtCname
              }).NodeMgmtCname

              foreach (${Mgmt Cname of Net IP Interface of other WinRM Remoting Target} in ${Mgmt Cnames of Net IP Interfaces of ALL OTHER WinRM Remoting Targets}) {
                #region |  |
                ${X.509v3 pre-PKI Server Authentication Certificate Info from CER} = $ConfigurationData.AllNodes.Where({
                  $_.NodeMgmtCname -eq ${Mgmt Cname of Net IP Interface of other WinRM Remoting Target}
                }).'CER File of Server Authentication cert for Mutual Authentication'

                ${X.509v3 pre-PKI Server Authentication Certificate Info from PFX} = $ConfigurationData.AllNodes.Where({
                  $_.NodeMgmtCname -eq ${Mgmt Cname of Net IP Interface of other WinRM Remoting Target}
                }).'PFX File of Server Authentication cert for Mutual Authentication'
                #endregion
                if (
                  $null -ne ${X.509v3 pre-PKI Server Authentication Certificate Info from CER} -and `
                  $null -ne ${X.509v3 pre-PKI Server Authentication Certificate Info from PFX}
                ) {
                  #region |  |
                  $Resource_Title_Precursor = -join $(
                    "Import on $NodeMgmtCname the cert allowing"
                    [System.Char]32
                    ${X.509v3 Server Authentication Certificate Info from CER}.Resource_Title
                  )
                  $Resource_Title = $Resource_Title_Precursor -replace '[^\w\d-\\ \.]','\\'
                  $Thumbprint = ${X.509v3 Server Authentication Certificate Info from PFX}.Thumbprint
                  $FriendlyName = ${X.509v3 Server Authentication Certificate Info from CER}.FriendlyName
                  ${.cer File FullName} = "${env:Pre-PKI CertFSOs}\$FriendlyName.cer"
                  #endregion
                  @{
                    Resource_Title       = $Resource_Title
                    Location             = 'LocalMachine'
                    Store                = 'My'
                    Thumbprint           = $Thumbprint
                    FriendlyName         = $FriendlyName
                    Path                 = ${.cer File FullName}
                    Ensure               = 'Present'
                    PsDscRunAsCredential = $PsDscRunAsCredential
                  }
                }
              }
            }
          )
          'Import Pre-PKI Client Authentication CER Files' = $(
            if ($null -ne $ConfigurationData) {
              #region | Credentials |
              $un = "$AD_NetBIOS 544"
              $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
              $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
              $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
              #endregion
              # We want to use the 'PFX File Collection of Client Authentication certs for Mutual Authentication' key-value pair because 
              # no other key-value pair provides the thumbprint for the Client Authentication certs being imported. 
              ${Information for Client Authentication CER Files Undergoing Import} = $ConfigurationData.AllNodes.Where({
                $_.NodeMgmtCname -eq $NodeMgmtCname
              }).'PFX File Collection of Client Authentication certs for Mutual Authentication' # <----- Yes, this is correct!
              if ($null -ne ${Information for Client Authentication CER Files Undergoing Import}) {
                foreach (${Information for Client Authentication CER File Undergoing Import} in ${Information for Client Authentication CER Files Undergoing Import}) {
                  #${Information for Client Authentication CER File Undergoing Import}.Resource_Title -match '^(?<Ignore>.+)\s(?<Three_Digit_Code>\d{3})$' > $null
                  ${Information for Client Authentication CER File Undergoing Import}.FriendlyName -match "^(?<Ignore_These_Characters>Local Account) $([System.Char]39)(?<Domain_NetBIOS_Name_OR_Cname_of_Config_Target_Mgmt_Interface>[0-9a-z-]+) (?<Three_Digit_Code>\d{3})$([System.Char]39)$([System.Char]36)" | Out-Null
                  #   "Local Account $([System.Char]39)$AD_NetBIOS ${Pseudo Primary Group ID}$([System.Char]39)"
                  $Resource_Title_Precursor = -join $(
                    "Import Client Authentication cert corresponding to"
                    [System.Char]32
                    "Local Account $AD_NetBIOS $($Matches['Three_Digit_Code'])"
                  )
                  $Resource_Title = $Resource_Title_Precursor -replace '[^\w\d-\\ \.]','\\'
                  $Thumbprint = ${Information for Client Authentication CER File Undergoing Import}.Thumbprint
                  $FriendlyName = ${Information for Client Authentication CER File Undergoing Import}.FriendlyName
                  ${.cer File FullName} = ${Information for Client Authentication CER File Undergoing Import}.Path -replace '\.pfx$','.cer'
                  if (Test-Path -Path ${.cer File FullName}) {
                    $Content = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(${.cer File FullName}))
                    @{
                      Resource_Title       = $Resource_Title
                      Location             = 'LocalMachine'
                      Store                = 'My'
                      Thumbprint           = $Thumbprint
                      FriendlyName         = $FriendlyName
                      Path                 = ${.cer File FullName}
                      Content              = $Content
                      Ensure               = 'Present'
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  }
                }
              }
            }
          )
          #endregion
          #endregion
          #region | !"Network Refined v2 with System account.ps1" |
          'Network Refined v2' = $(
            #region |  |
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            #endregion
            @{
              #region | OS Instance-level Network Items |
              'OS Instance' = $(
                @{
                  'Dns Client Global Setting' = $(
                    #region |  |
                    $SuffixSearchList = $(
                      ${Registered Organization}
                      "ad.${Registered Organization}"
                      'abc.def.xyz'
                      'fabrikam.com'
                      'fourthcoffee.com'
                    )
                    $Resource_Title = "DnsClientGlobalSetting on the $NodeMgmtCname OS Instance"
                    #endregion
                    @{
                      Resource_Title       = $Resource_Title
                      IsSingleInstance     = 'Yes'
                      DevolutionLevel      = 0
                      SuffixSearchList     = $SuffixSearchList
                      UseDevolution        = $true
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                  'Hosts File Entry Collection' = $(
                    @(
                      $(
                        $HostName = 'NoHost0'
                        @{
                          Resource_Title       = "Hosts file entry for $HostName on $NodeMgmtCname"
                          HostName             = $HostName
                          IPAddress            = '192.168.11.10'
                          Ensure               = 'Present'
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      $(
                        $HostName = 'NoHost1'
                        @{
                          Resource_Title       = "Hosts file entry for $HostName on $NodeMgmtCname"
                          HostName             = $HostName
                          IPAddress            = '192.168.11.11'
                          Ensure               = 'Present'
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                    )
                  )
                  'Windows Internet Name Service' = $(
                    @{
                      Resource_Title       = "Legacy WINS Settings on $NodeMgmtCname"
                      IsSingleInstance     = 'Yes'
                      EnableDns            = $false # DISABLE using DNS for WINS name resolution
                      EnableLmHosts        = $false
                      PsDscRunAsCredential = $PsDscRunAsCredential
                    }
                  )
                }
              )
              #endregion
              #region | Network Adapters Config + IPv4/IPv6 Interface Settings |
              'Adapters Config' = $(
                @(
                  $(${VLAN Title} = 'Administrative Control'; ${Network Adapter Index} = '2'; ${Adapter Hardware Type} = [AdapterHardwareType]::Mc;
                    #region |  |
                    ${VLAN ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${VLAN Title}.txt" -ErrorAction 'SilentlyContinue'
                    if ($null -ne ${VLAN ID-Binary}) {
                      ${VLAN ID-Base10} = [System.Convert]::ToInt32(${VLAN ID-Binary},2)
                      ${VLAN ID-Base10 Padded} = ${VLAN ID-Base10}.ToString('0000')
                    }
                    $InterfaceName = "${VLAN Title} ${Network Adapter Index} ${Adapter Hardware Type} Network Adapter"
                    ${MAC Address Raw} = $(
                      $HT = @{
                        Path             = "$Statics\MAC Address Space"
                        Recurse          = $true
                        File             = $true
                        ErrorAction      = 'SilentlyContinue'
                        PipelineVariable = 'file'
                      }
                      Get-ChildItem @HT | Where-Object -FilterScript {
                        $file.Name -eq "$NodeMgmtCname ${VLAN Title} ${Network Adapter Index}.txt"
                      } | Get-Content
                    )
                    ${MAC Address Hypenated} = $(
                      if ($null -ne ${MAC Address Raw}) {
                        $ByteArray = foreach ($i in 0..(${MAC Address Raw}.Length - 1)) {
                          [System.String]${MAC Address Raw}[$($foreach.Current)] + [System.String]${MAC Address Raw}[$($foreach.Current + 1)]  
                          [System.Void]$foreach.MoveNext()
                        }
                        [System.String]::Join('-',$ByteArray).ToUpper()
                      }
                    )
                    ${MAC Address Colons} = ${MAC Address Hypenated} -replace '-',':'

                    $DriverDescription    = 'Microsoft Hyper-V Network Adapter'
                    $InterfaceDescription = 'Microsoft Hyper-V Network Adapter'
                    $PhysicalMediaType    = 'Unspecified'
                    #endregion
                    @{
                      #region | Network Adapter |
                      #region |  |
                      'VLAN Title'             = ${VLAN Title}
                      'Network Adapter Index'  = ${Network Adapter Index}.ToLower()
                      'Adapter Hardware Type'  = ${Adapter Hardware Type}
                      'VLAN ID-Binary'         = ${VLAN ID-Binary}
                      'VLAN ID-Base10'         = ${VLAN ID-Base10}
                      DriverDescription        = $DriverDescription
                      PhysicalMediaType        = $PhysicalMediaType
                      'MAC Address Raw'        = ${MAC Address Raw}
                      'Connected vSwitch Name' = 'SET-enabled External vSwitch'
                      #endregion
                      'Net Adapter Name' = $(
                        #region |  |
                        $NewName = $InterfaceName
                        $Status = 'Up'
                        $Resource_Title = "$NewName on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          NewName              = $NewName
                          MacAddress           = ${MAC Address Hypenated}
                          DriverDescription    = $DriverDescription
                          Status               = $Status
                          PhysicalMediaType    = $PhysicalMediaType
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Net Adapter State' = $(
                        #region |  |
                        $Name = $InterfaceName
                        $State = 'Enabled'
                        $Resource_Title = "Enable $Name Network Adapter on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          State                = $State
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Set of Advanced Properties for this Network Adapter' = $(
                        #region |  |
                        $NetworkAdapterName = $InterfaceName
                        # $NetworkAdapterName = ''
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Sort-Object -Property 'DisplayName' | Format-Table -AutoSize
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | Format-Table -AutoSize
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | % 'DisplayName' | Set-Clipboard
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Format-Table -AutoSize
                        #endregion
                        @(
                          $($RegistryKeyword = 'VlanID'; $RegistryValue = '0'; # <----- This has to be zero?
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # VLAN ID
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'NetworkAddress'; $RegistryValue = ${MAC Address Raw};
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Network Address
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*IPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPv4 Checksum Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TCPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # TCP Checksum Offload (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv4'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload Version 2 (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv6'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload Version 2 (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TCPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # TCP Checksum Offload (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*IPsecOffloadV2'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPSec Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*JumboPacket'; $RegistryValue = '9014';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Jumbo Packet
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*MaxRssProcessors'; $RegistryValue = '16';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Max Number of RSS Processors
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*NetworkDirect'; $RegistryValue = '1'; # NetworkDirect is RDMA while Packet Direct is something else. 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Network Direct (RDMA) | Also inspect the 'Remote Direct Memory Access' key-value pair for this Network Adapter |
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*NumRssQueues'; $RegistryValue = '16';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum Number of RSS Queues
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*PacketDirect'; $RegistryValue = '0'; # <----- Related to SDN/Network Virtualization/Network ATC... so just leave alone for now |
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Packet Direct
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RscIPv4'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Recv Segment Coalescing (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RscIPv6'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Recv Segment Coalescing (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSS'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Side Scaling
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RssBaseProcNumber'; $RegistryValue = '0'; 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # RSS Base Processor Number
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RssMaxProcNumber'; $RegistryValue = '63';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum RSS Processor Number
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSSProfile'; $RegistryValue = '4'; 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # RSS Profile
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'ForwardingOptimization'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Forwarding Optimization
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'ReceiveBufferSize'; $RegistryValue = '8192';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Buffer Size
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'SendBufferSize'; $RegistryValue = '1024';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Send Buffer Size
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                        )
                      )
                      'Binding States on this Network Adapter' = $()
                      '_Firewall Rule Set' = $(@(@{}))
                      '_Firewall Profile Set' = $(@(@{}))
                      #endregion
                      #region | Collections of Settings for the IPv4 Interface on the Network Adapter |
                      'All Settings on the IPv4 Interface bound to this Network Adapter' = $(
                        #region |  |
                        $AddressFamily = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.AddressFamily]::IPv4
                        $InterfaceAlias = $InterfaceName # The 'InterfaceName' attribute of a Network Adapter is the 'InterfaceAlias' of the Net IP Interface
                        ${State of DHCP Client on IPv4 Interface}  = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.Dhcp]::Enabled

                        $IPAddressFilePath = "$Statics\MaxIP\IPv4\${VLAN Title} ${VLAN ID-Base10 Padded}\$NodeMgmtCname ${Network Adapter Index}.txt"
                        $IsIPAddressFilePresent = Test-Path -Path $IPAddressFilePath
                        if ($IsIPAddressFilePresent) {
                          ${IPAddress No CIDR} = Get-Content -Path $IPAddressFilePath | ConvertTo-DottedDecimalIP | Select-Object -ExpandProperty 'IPAddressToString'
                          ${IPAddress + CIDR} = ${IPAddress No CIDR} + '/' + '22'
                        }

                        <#
                          ${Default Gateway IPv4 Address} = [System.Environment]::GetEnvironmentVariables('Machine')["Default Gateway $_VLAN $AddressFamily Address"]
                          
                          ${_DNS Server IPv4 Address} = $ConfigurationData.AllNodes.Where({
                            $_.NodeCname -eq ${DSC Authoring Station Mgmt Cname}
                          }).'RESERVED IPv4 Addr-DnsServer Global'.IPv4Address
                          $path = "$Statics\IPs\0010 $vlan10\$DomainCtrl00Cname 8 $([aht]::Mc) IP Address.txt"
                          $IsPresent = Test-Path -Path $path
                          if ($IsPresent) {
                            ${DNS Server IPv4 Address in Binary} = Get-Content -Path $path
                            ${DNS Server IPv4 Address} = ConvertTo-DottedDecimalIP -IPAddress ${DNS Server IPv4 Address in Binary} | Select-Object -ExpandProperty 'IPAddressToString'
                          }
                        #>
                        #endregion
                        @{
                          'Consumed by DHCP Server' = $(
                            #region |  |
                            ${Name of DHCP Reservation} = "$NodeMgmtCname ${Network Adapter Index} ${Adapter Hardware Type} within ${VLAN Title}"
                            $Resource_Title = "DHCP Reservation Titled ${Name of DHCP Reservation}"  -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            if ($IsIPAddressFilePresent) {
                              ${IPAddress No CIDR} = Get-Content -Path $IPAddressFilePath | ConvertTo-DottedDecimalIP | Select-Object -ExpandProperty 'IPAddressToString'
                              ${IPAddress + CIDR} = ${IPAddress No CIDR} + '/' + '22'
                              $ScopeId = Get-NetworkSummary -IPAddress ${IPAddress + CIDR} | Select-Object -ExpandProperty 'NetworkAddress' | Select-Object -ExpandProperty 'IPAddressToString'
                              @{
                                'Reservation' = $(
                                  @{
                                    Resource_Title   = $Resource_Title
                                    IPAddress        = ${IPAddress No CIDR}
                                    ScopeID          = $ScopeID
                                    ClientMACAddress = ${MAC Address Hypenated}
                                    AddressFamily    = $AddressFamily
                                    Name             = ${Name of DHCP Reservation}
                                    Ensure           = 'Present'
                                  }
                                )
                                'Net IP Interface-level Options' = $(
                                  @{
                                    'Option 001' = $()
                                    'Option 003' = $()
                                    'Option 006' = $()
                                    'Option 015' = $()
                                  }
                                )
                              }
                            }
                          )
                          'Consumed by DNS Server' = $()
                          'State of DHCP Client on IPv4 Interface' = ${State of DHCP Client on IPv4 Interface}
                          'IPv4 Interface on Network Adapter' = $()
                          'Static or Dynamic IP Address of IPv4 Interface' = $(
                            # Get-NetIPAddress -AddressFamily $AddressFamily -InterfaceAlias $InterfaceAlias
                            $Resource_Title = "$AddressFamily Address with alias $InterfaceAlias on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                            @{
                              Resource_Title       = $Resource_Title
                              AddressFamily        = $AddressFamily
                              InterfaceAlias       = $InterfaceAlias
                              IPAddress            = ${IPAddress + CIDR}
                              KeepExistingAddress  = $false
                              PsDscRunAsCredential = $PsDscRunAsCredential
                              # While the below key-value pairs are *NOT* properties on the 'IPAddress' DSC Resource,
                              # they're used in other areas of this Environment Data file. 
                              Dhcp                 = ${State of DHCP Client on IPv4 Interface}
                              IPAddressFilePath    = $IPAddressFilePath
                            }
                          )
                        }
                      )
                      #endregion
                      #region | Collections of Settings for the IPv6 Interface on the Network Adapter |
                      'All Settings on the IPv6 Interface bound to this Network Adapter' = $()
                      #endregion
                    }
                  )
                  $(${VLAN Title} = 'Cheddar'; ${Network Adapter Index} = 'm'; ${Adapter Hardware Type} = [AdapterHardwareType]::Mc;
                    #region |  |
                    ${VLAN ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${VLAN Title}.txt" -ErrorAction 'SilentlyContinue'
                    if ($null -ne ${VLAN ID-Binary}) {
                      ${VLAN ID-Base10} = [System.Convert]::ToInt32(${VLAN ID-Binary},2)
                      ${VLAN ID-Base10 Padded} = ${VLAN ID-Base10}.ToString('0000')
                    }
                    $InterfaceName = "${VLAN Title} ${Network Adapter Index} ${Adapter Hardware Type} Network Adapter"
                    ${MAC Address Raw} = $(
                      $HT = @{
                        Path             = "$Statics\MAC Address Space"
                        Recurse          = $true
                        File             = $true
                        ErrorAction      = 'SilentlyContinue'
                        PipelineVariable = 'file'
                      }
                      Get-ChildItem @HT | Where-Object -FilterScript {
                        $file.Name -eq "$NodeMgmtCname ${VLAN Title} ${Network Adapter Index}.txt"
                      } | Get-Content
                    )
                    ${MAC Address Hypenated} = $(
                      if ($null -ne ${MAC Address Raw}) {
                        $ByteArray = foreach ($i in 0..(${MAC Address Raw}.Length - 1)) {
                          [System.String]${MAC Address Raw}[$($foreach.Current)] + [System.String]${MAC Address Raw}[$($foreach.Current + 1)]  
                          [System.Void]$foreach.MoveNext()
                        }
                        [System.String]::Join('-',$ByteArray).ToUpper()
                      }
                    )
                    ${MAC Address Colons} = ${MAC Address Hypenated} -replace '-',':'

                    $DriverDescription    = 'Microsoft Hyper-V Network Adapter'
                    $InterfaceDescription = 'Microsoft Hyper-V Network Adapter'
                    $PhysicalMediaType    = 'Unspecified'
                    #endregion
                    @{
                      #region | Network Adapter |
                      #region |  |
                      'VLAN Title'             = ${VLAN Title}
                      'Network Adapter Index'  = ${Network Adapter Index}.ToLower()
                      'Adapter Hardware Type'  = ${Adapter Hardware Type}
                      'VLAN ID-Binary'         = ${VLAN ID-Binary}
                      'VLAN ID-Base10'         = ${VLAN ID-Base10}
                      DriverDescription        = $DriverDescription
                      PhysicalMediaType        = $PhysicalMediaType
                      'MAC Address Raw'        = ${MAC Address Raw}
                      'Connected vSwitch Name' = 'SET-enabled External vSwitch'
                      #endregion
                      'Net Adapter Name' = $(
                        #region |  |
                        $NewName = $InterfaceName
                        $Status = 'Up'
                        $Resource_Title = "$NewName on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          NewName              = $NewName
                          MacAddress           = ${MAC Address Hypenated}
                          DriverDescription    = $DriverDescription
                          Status               = $Status
                          PhysicalMediaType    = $PhysicalMediaType
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Net Adapter State' = $(
                        #region |  |
                        $Name = $InterfaceName
                        $State = 'Enabled'
                        $Resource_Title = "Enable $Name Network Adapter on $NodeMgmtCname" -replace '[^a-z0-9- _\.]','\'
                        #endregion
                        @{
                          Resource_Title       = $Resource_Title
                          Name                 = $Name
                          State                = $State
                          PsDscRunAsCredential = $PsDscRunAsCredential
                        }
                      )
                      'Set of Advanced Properties for this Network Adapter' = $(
                        #region |  |
                        $NetworkAdapterName = $InterfaceName
                        # $NetworkAdapterName = ''
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Sort-Object -Property 'DisplayName' | Format-Table -AutoSize
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | Format-Table -AutoSize
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName -RegistryKeyword $RegistryKeyword | % 'DisplayName' | Set-Clipboard
                        # Get-NetAdapterAdvancedProperty -Name $NetworkAdapterName | Select-Object -Property 'DisplayName','DisplayValue','RegistryKeyword','RegistryValue' | Format-Table -AutoSize
                        #endregion
                        @(
                          $($RegistryKeyword = 'VlanID'; $RegistryValue = '0'; # <----- This has to be zero?
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # VLAN ID
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'NetworkAddress'; $RegistryValue = ${MAC Address Raw};
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Network Address
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*IPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPv4 Checksum Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TCPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # TCP Checksum Offload (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv4'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload Version 2 (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*LsoV2IPv6'; $RegistryValue = '0';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Large Send Offload Version 2 (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*TCPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # TCP Checksum Offload (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*IPsecOffloadV2'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # IPSec Offload
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*JumboPacket'; $RegistryValue = '9014';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Jumbo Packet
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*MaxRssProcessors'; $RegistryValue = '16';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Max Number of RSS Processors
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*NetworkDirect'; $RegistryValue = '1'; # NetworkDirect is RDMA while Packet Direct is something else. 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Network Direct (RDMA) | Also inspect the 'Remote Direct Memory Access' key-value pair for this Network Adapter |
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*NumRssQueues'; $RegistryValue = '16';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum Number of RSS Queues
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*PacketDirect'; $RegistryValue = '0'; # <----- Related to SDN/Network Virtualization/Network ATC... so just leave alone for now |
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Packet Direct
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RscIPv4'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Recv Segment Coalescing (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RscIPv6'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Recv Segment Coalescing (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSS'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Side Scaling
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RssBaseProcNumber'; $RegistryValue = '0'; 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # RSS Base Processor Number
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RssMaxProcNumber'; $RegistryValue = '63';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum RSS Processor Number
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSSProfile'; $RegistryValue = '4'; 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # RSS Profile
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'ForwardingOptimization'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Forwarding Optimization
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'ReceiveBufferSize'; $RegistryValue = '8192';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Buffer Size
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'SendBufferSize'; $RegistryValue = '1024';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Send Buffer Size
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                        )
                      )
                      'Binding States on this Network Adapter' = $()
                      '_Firewall Rule Set' = $(@(@{}))
                      '_Firewall Profile Set' = $(@(@{}))
                      #endregion
                      #region | Collections of Settings for the IPv4 Interface on the Network Adapter |
                      'All Settings on the IPv4 Interface bound to this Network Adapter' = $(
                        #region |  |
                        $AddressFamily = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.AddressFamily]::IPv4
                        $InterfaceAlias = $InterfaceName # The 'InterfaceName' attribute of a Network Adapter is the 'InterfaceAlias' of the Net IP Interface
                        ${State of DHCP Client on IPv4 Interface}  = [Microsoft.PowerShell.Cmdletization.GeneratedTypes.NetIPInterface.Dhcp]::Enabled

                        $IPAddressFilePath = "$Statics\MaxIP\IPv4\${VLAN Title} ${VLAN ID-Base10 Padded}\$NodeMgmtCname ${Network Adapter Index}.txt"
                        $IsIPAddressFilePresent = Test-Path -Path $IPAddressFilePath
                        if ($IsIPAddressFilePresent) {
                          ${IPAddress No CIDR} = Get-Content -Path $IPAddressFilePath | ConvertTo-DottedDecimalIP | Select-Object -ExpandProperty 'IPAddressToString'
                          ${IPAddress + CIDR} = ${IPAddress No CIDR} + '/' + '22'
                        }

                        <#
                          ${Default Gateway IPv4 Address} = [System.Environment]::GetEnvironmentVariables('Machine')["Default Gateway $_VLAN $AddressFamily Address"]
                          
                          ${_DNS Server IPv4 Address} = $ConfigurationData.AllNodes.Where({
                            $_.NodeCname -eq ${DSC Authoring Station Mgmt Cname}
                          }).'RESERVED IPv4 Addr-DnsServer Global'.IPv4Address
                          $path = "$Statics\IPs\0010 $vlan10\$DomainCtrl00Cname 8 $([aht]::Mc) IP Address.txt"
                          $IsPresent = Test-Path -Path $path
                          if ($IsPresent) {
                            ${DNS Server IPv4 Address in Binary} = Get-Content -Path $path
                            ${DNS Server IPv4 Address} = ConvertTo-DottedDecimalIP -IPAddress ${DNS Server IPv4 Address in Binary} | Select-Object -ExpandProperty 'IPAddressToString'
                          }
                        #>
                        #endregion
                        @{
                          'Consumed by DHCP Server' = $(
                            #region |  |
                            ${Name of DHCP Reservation} = "$NodeMgmtCname ${Network Adapter Index} ${Adapter Hardware Type} within ${VLAN Title}"
                            $Resource_Title = "DHCP Reservation Titled ${Name of DHCP Reservation}"  -replace '[^a-z0-9- _\.]','\'
                            #endregion
                            if ($IsIPAddressFilePresent) {
                              ${IPAddress No CIDR} = Get-Content -Path $IPAddressFilePath | ConvertTo-DottedDecimalIP | Select-Object -ExpandProperty 'IPAddressToString'
                              ${IPAddress + CIDR} = ${IPAddress No CIDR} + '/' + '22'
                              $ScopeId = Get-NetworkSummary -IPAddress ${IPAddress + CIDR} | Select-Object -ExpandProperty 'NetworkAddress' | Select-Object -ExpandProperty 'IPAddressToString'
                              @{
                                'Reservation' = $(
                                  @{
                                    Resource_Title   = $Resource_Title
                                    IPAddress        = ${IPAddress No CIDR}
                                    ScopeID          = $ScopeID
                                    ClientMACAddress = ${MAC Address Hypenated}
                                    AddressFamily    = $AddressFamily
                                    Name             = ${Name of DHCP Reservation}
                                    Ensure           = 'Present'
                                  }
                                )
                                'Net IP Interface-level Options' = $(
                                  @{
                                    'Option 001' = $()
                                    'Option 003' = $()
                                    'Option 006' = $()
                                    'Option 015' = $()
                                  }
                                )
                              }
                            }
                          )
                          'Consumed by DNS Server' = $()
                          'State of DHCP Client on IPv4 Interface' = ${State of DHCP Client on IPv4 Interface}
                          'IPv4 Interface on Network Adapter' = $()
