                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum Number of RSS Queues
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*PacketDirect'; $RegistryValue = '0'; # <----- Related to SDN/Network Virtualization/Network ATC... so just leave alone for now |
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Packet Direct
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RscIPv4'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Recv Segment Coalescing (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RscIPv6'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Recv Segment Coalescing (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSS'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Side Scaling
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RssBaseProcNumber'; $RegistryValue = '0'; 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # RSS Base Processor Number
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RssMaxProcNumber'; $RegistryValue = '63';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Maximum RSS Processor Number
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*RSSProfile'; $RegistryValue = '4'; 
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # RSS Profile
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv4'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv4)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = '*UDPChecksumOffloadIPv6'; $RegistryValue = '3';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # UDP Checksum Offload (IPv6)
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'ForwardingOptimization'; $RegistryValue = '1';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Forwarding Optimization
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'ReceiveBufferSize'; $RegistryValue = '8192';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Receive Buffer Size
                            @{
                              Resource_Title       = $Resource_Title
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
                          $($RegistryKeyword = 'SendBufferSize'; $RegistryValue = '1024';
                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Send Buffer Size
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
