                      #endregion
                    }
                  )
                  $(${VLAN Title} = 'Provolone'; ${Network Adapter Index} = '2'; ${Adapter Hardware Type} = [AdapterHardwareType]::Mc;
                    #region |  |
                    ${VLAN ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${VLAN Title}.txt" -ErrorAction 'SilentlyContinue'
