          #endregion
          #region | !"Windows Features, Roles, and Role Services-! Blank DependsOn with System account.ps1" |
          Purpose_0f_Instance = 'New_AD_Forest'
          Configuration_Names = @('New_AD_Forest')
          'Windows Features' = $(
            #region |  |
            #region | Credentials |
            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Credential = [PSCredential]::New($un,$pw)

            $un = "$AD_NetBIOS 544"
            $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            ${DNS HT} = ${Clone Me DNS HT}.Clone()
            ${DNS HT}['Resource_Title'] = ${DNS HT}['Resource_Title'] -replace '%_NodeCname_%',$NodeMgmtCname
            ${DNS HT}.Add('Credential',$Credential)
            ${DNS HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${RSAT-DNS-Server HT} = ${Clone Me RSAT-DNS-Server HT}.Clone()
