            ${RSAT-AD-PowerShell HT}.Add('Credential',$Credential)
            ${RSAT-AD-PowerShell HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${RSAT-AD-AdminCenter HT} = ${Clone Me RSAT-AD-AdminCenter HT}.Clone()
            ${RSAT-AD-AdminCenter HT}['Resource_Title'] = ${RSAT-AD-AdminCenter HT}['Resource_Title'] -replace '%_NodeCname_%',$NodeMgmtCname
            ${RSAT-AD-AdminCenter HT}.Add('Credential',$Credential)
            ${RSAT-AD-AdminCenter HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${RSAT-ADDS-Tools HT} = ${Clone Me RSAT-ADDS-Tools HT}.Clone()
