            ${RSAT-ADDS-Tools HT}.Add('Credential',$Credential)
            ${RSAT-ADDS-Tools HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${GPMC HT} = ${Clone Me GPMC HT}.Clone()
            ${GPMC HT}['Resource_Title'] = ${GPMC HT}['Resource_Title'] -replace '%_NodeCname_%',$NodeMgmtCname
            ${GPMC HT}.Add('Credential',$Credential)
            ${GPMC HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            # ${RSAT-DHCP HT} = ${Clone Me RSAT-DHCP HT}.Clone()
            # ${RSAT-DHCP HT}['Resource_Title'] = ${RSAT-DHCP HT}['Resource_Title'] -replace '%_NodeCname_%',$NodeMgmtCname
            # ${RSAT-DHCP HT}.Add('Credential',$Credential)
            # ${RSAT-DHCP HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)
            #endregion
            if ( # Desktop Experience |
              -not (${Windows Server Image Index} % 2)) {
              @(
                ${DNS HT}
                ${RSAT-DNS-Server HT}
                ${AD-Domain-Services HT}
                ${RSAT-AD-PowerShell HT}
                ${RSAT-AD-AdminCenter HT}
                ${RSAT-ADDS-Tools HT}
