                            #region | Individual Accounts |
                            [System.String[]]$Collection0 = @(
                              $ConfigurationData.AllNodes.Where({ # Going to OMIT the break-glass accounts from membership in Schema Admins |
                                $_.Life          -eq $false             -and `
