              #region | delete? "Wait for DHCP server domain-join.ps1" |
              '_WaitFor DHCP server domain-join' = $(
                $SelfRef = $()
                @{
                  Reference = $(
                    $TargetNodeCName = $DhcpServer00Cname
                    $TargetNodeName = [QuickMgmtCnameConversion]::CN($TargetNodeCName)
                    $NodeName = $TargetNodeName

                    if ($null -ne $ConfigurationData) {
                      ${Join Workstation to Domain} = $ConfigurationData.AllNodes.Where({
                        $_.NodeName -eq $NodeName
                      }).'Join Workstation to Domain'.Resource_Title

                      $ResourceName = "[Computer]$(${Join Workstation to Domain}.Resource_Title)"
                    }

                    $un = "$AD_NetBIOS 544"
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                  $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                  )
                  Resource_Title       = "WaitFor $TargetNodeCName Domain-Join"
                  ResourceName         = $ResourceName
                  NodeName             = $NodeName
                  RetryIntervalSec     = 5
                  RetryCount           = (12 * 3) # 3 minutes
                  ThrottleLimit        = 32
                  PsDscRunAsCredential = $PsDscRunAsCredential
                }
              )
              #endregion
              #region | "AD Authorize Dhcp Servers in AD.ps1" |
              <#
                'Authorize 1st Unclustered Dhcp Server In AD' = $(
                  $SelfRef = $()
                  @{
                    Reference = $( # dhcpAvocado |
                      $cname = $DhcpServer00Cname

                      $VLAN_ID = 10
                      $_VLAN = Get-Item -Path "Variable:\vlan$($VLAN_ID)" | Select-Object -ExpandProperty 'Value'
                      $ScopeId = "10.$Octet2.$VLAN_ID.0"
                      $InterfaceName = "$_VLAN 0"
                      ${DHCP Server IPv4 Address} = [System.Environment]::GetEnvironmentVariables('Machine')["RESERVED IPv4 Addr $cname $InterfaceName"]

                      # Why not use an Enterprise Admin? Why perform on the DHCP server, for that matter?
                      # Because Enterprise Admin does not also have membership in local Administrators! 
                      $UpnPrefix = "$AD_NetBIOS 500"
                      $UpnSuffix = $AD_DNS
                      $upn = "$UpnPrefix@$UpnSuffix"
                      $un = 'Administrator'
                      $HT = @{Target = $upn; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                      $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                    $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                    )
                    Resource_Title       = "Add database of DHCP Server $cname in DC"
                    IsSingleInstance     = 'Yes'
                    DnsName              = [QuickMgmtCnameConversion]::CN($cname) + '.' + $AD_DNS
                    IPAddress            = ${DHCP Server IPv4 Address}
                    Ensure               = 'Present'
                    PsDscRunAsCredential = $PsDscRunAsCredential
                  }
                )
              #>
