                    $Resource_Title = "AD Security Group_$($GroupName)" -replace '[^\w\d-\\ \.]','\\'
                    #endregion
                    @{
                      Resource_Title        = "AD Security Group_$($_GroupName)"
                      GroupName             = $GroupName
                      Path                  = ${Gs OU}
                      AdminDescription      = "Group_"
                      Category              = 'Security'
                      Description           = $Description
                      DisplayName           = $GroupName
                      DomainController      = ${FQDN of AD Forest Creator}
                      GroupScope            = $GroupScope
                      ManagedBy             = "CN=Administrator,OU=Us,OU=$LabelGamma,OU=Org,$AD_DN"
                      Members               = $(
                        if ($null -ne $ConfigurationData) {
                          $MainHashTable = $ConfigurationData.AllNodes.Where({
                            $_.Life          -eq $true             -and `
                            $_.SuperEmpire   -eq 'Microsoft'        -and `
                            $_.Empire        -eq 'VM'               -and `
                            $_.SubEmpire     -eq 'Windows Server'   -and `
                            $_.SuperDominion -match '^Yes'          -and `
                            $_.Dominion      -eq 'Active Directory' -and `
                            $_.Kingdom       -eq 'New AD Forest'
                          }).'Everything AD'.$label

                          if ($MainHashTable) {
                            $CollectionOfHashTables = foreach ($Entry in $MainHashTable.GetEnumerator()) {
                              if ($Entry.Key -match '^AD User Account') {
                                $Entry
                              }
                            }

                            [System.String[]]$UserNames = for ($i = 0; $i -lt $CollectionOfHashTables.Count; $i++) {
                              $HT = $CollectionOfHashTables[$i]
                              $HT.Value.UserName
                            }

                            ($UserNames).Where({$_ -ne ''})
                          }
                        }
                      )
                      MembershipAttribute   = 'SamAccountName'
                      Notes                 = "All AD User accounts in the $label OU. Purpose of group is enforcement of AD tiering at Security $label.`n`nIdea for later: populate group via Scheduled Task?"

