              #region | "A-D Windows Management Instrumentation Filters.ps1" |
              <#
                $cname = $DomainCtrl00Cname; $sess = ctpd $cname "$AD_NetBIOS 544"
                icm -Session $sess {
                  $path = "$env:DSC_CFG_ROOT\modules\5.1"; $dir = try {Get-Item -Path $path -ErrorAction 'Stop'} catch {New-Item -Path $path -ItemType 'Directory' -Force}
                  Copy-Item -Path "$env:DSC_CFG_ROOT\AD-Dependent Modules\Manage-WmiFilters.zip" -Destination $path
                }
              #>
              Unzip_AD_Dependent_Modules = @{
                Resource_Title = "Unzip AD-Dependent Modules"
                Path          = "$env:DSC_CFG_ROOT\AD-Dependent Modules\Manage-WmiFilters.zip"
                #Path           = "$env:DSC_CFG_ROOT\modules\5.1\Manage-WmiFilters.zip"
                Destination    = "$env:ProgramFiles\WindowsPowerShell\Modules"
                Validate       = $true
                Checksum       = 'SHA-256'
                Force          = $true
                Ensure         = 'Present'
              }
              Windows_Management_Instrumentation_Filters = @( # Create WMI Filters but don't yet link to a GPO |
                <# Microsoft WMI Code Creator v1.0 |
                  start msedge.exe 'https://www.microsoft.com/en-us/download/details.aspx?id=8572'
                #>
                @{ # Windows 11 All Editions |
                  Reference = $(
                    $un = 'DC_LocalAdmin'
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                        $Credential = [PSCredential]::New($un,$pw)

                    $un = 'DC_LocalAdmin'
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                    $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                  )
                  Name_of_WMI_Filter    = "Windows 11 All Editions"
                  Desc_of_WMI_Filter    = "All editions of client Windows 11 that can join a domain"
                  WQL_Expressions       = @("SELECT Version,ProductType FROM Win32_OperatingSystem WHERE Version LIKE '10.0.22%' AND ProductType = '1'")
                  TargetNamespace       = "root\CIMv2"
                  EscapedName_WMIFilter = "Windows 11 All Editions"
                  WMI_Author_UserName   = "$AD_NetBIOS 544"
                  Credential            = $Credential
                  PsDscRunAsCredential  = $PsDscRunAsCredential
                }
                @{ # Windows Server (Desktop Experience) |
                  Reference = $(
                    $un = 'DC_LocalAdmin'
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                        $Credential = [PSCredential]::New($un,$pw)

                    $un = 'DC_LocalAdmin'
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                    $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                  )
                  Name_of_WMI_Filter    = "Windows Server (Desktop Experience)"
                  Desc_of_WMI_Filter    = "All instances of Windows Server with a GUI regardless of Version, Edition, or any other attribute"
                  WQL_Expressions       = @("SELECT * FROM CIM_DataFile WHERE Name='$env:SystemDrive\\Windows\\explorer.exe'","SELECT ProductType from Win32_OperatingSystem WHERE ProductType != '1'")        #WQL_Expressions    = @("SELECT * FROM CIM_DataFile WHERE Name='C:\\Windows\\explorer.exe'","SELECT ProductType from Win32_OperatingSystem WHERE ProductType != '1'")
                  TargetNamespace       = "root\CIMv2"
                  EscapedName_WMIFilter = "Windows Server \Desktop Experience\"
                  WMI_Author_UserName   = "$AD_NetBIOS 544"
                  Credential            = $Credential
                  PsDscRunAsCredential  = $PsDscRunAsCredential
                }
                @{ # Windows Defender Credential Guard |
                  Reference = $(
                    $un = 'DC_LocalAdmin'
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                        $Credential = [PSCredential]::New($un,$pw)

                    $un = 'DC_LocalAdmin'
                    $HT = @{Target = $un; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
                    $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                    $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                  )
                  Name_of_WMI_Filter    = "Windows Defender Credential Guard"
                  Desc_of_WMI_Filter    = "All instances of Windows 10\\11 Enterprise, Windows 10\\11 Education, and any instance of Windows Server that is NOT a domain controller."
                  WQL_Expressions       = @("SELECT * FROM Win32_OperatingSystem WHERE ProductType!='2' or Caption like '%Enterprise%' or Caption like '%Education%'")
                  TargetNamespace       = "root\CIMv2"
