                    MigrationTableFullName = "$adVol\GPO Migration Tables\security08_Harden Domain-Join Operations_CVE-2022-38042.migtable"
                    CreateIfNeeded         = $true
                    Status                 = 'AllSettingsEnabled'
                    Ensure                 = 'Present'
