              #region | "A-D Computer Objects.ps1" |
              <# Important |
                Try to avoid promoting member servers to domain controllers. The Owner of the AD computer object representing the DC
                remains the account that performed the domain-join (or initial AD Computer object creation) which is undesirable. 
                If a member server gets promoted to a DC, be sure to confirm that an appropriately privileged account owns that object. 
                So only members of Domain Admins should hold Ownership over AD Computers that are DCs? 
              #>
              AD_Computer_Objects_T0 = @(
                #region | AD Computers that host a DHCP server |
                @{ # dhcpAvocado |
                  ADComputer_Resource_Title         = "AD Computer_dhcpAvocado"
                  ComputerName                      = 'dhcpAvocado' | ForEach-Object -Process {Get-ChildItem -ErrorAction 'SilentlyContinue' -Path $Statics -Recurse -Filter "*$_ ComputerName.txt"} | Get-Content
                  Path                              = "OU=DHCP,OU=Cs,OU=$LabelGamma,OU=Org,$AD_DN"
                  Description                       = "First unclustered DHCP Server"
                  DisplayName                       = "Unclustered DHCP Server No. 1"
                  DnsHostName                       = "$('dhcpAvocado' | ForEach-Object -Process {Get-ChildItem -ErrorAction 'SilentlyContinue' -Path $Statics -Recurse -Filter "*$_ ComputerName.txt"} | Get-Content).$AD_DNS"
                  DomainController                  = "$($NodeMgmtCname | ForEach-Object -Process {Get-ChildItem -ErrorAction 'SilentlyContinue' -Path $Statics -Recurse -Filter "*$_ ComputerName.txt"} | Get-Content).$AD_DNS"
                  #Location                         = "use the Microsoft-defined syntax for this Location attribute" # 
                  EnabledOnCreation                 = $false
                  Manager                           = "CN=OverPrivDomainJoinT0,OU=Us,OU=Tier 0,OU=Org,$AD_DN"
                  RestoreFromRecycleBin             = $false      # Flip to $true in production. 
                  # ServicePrincipalNames           = Array of SPNs for this AD Computer object... if only I knew what an SPN was. 
                  # UserPrincipalName               = What would be the UPN of an AD Computer object? Why would the principal of a USER principal name apply to a COMPUTER object? Perhaps UPN should've been 'APN' or 'UAPN'. 
                  RbKCD                             = $null    # @() # Resource-Based Kerberos Constrained Delegation
                  ODJ_ReqFile_Path                  = $null
                  #Credential_Create_Computer_Object = $($un = 'CreateComputers0-T0'; [PSCredential]::New("$AD_NetBIOS\$un",$(Get-StoredCredential -Target $un | % 'Password')))
                  Ensure                            = 'Present'

                  ADObjectEnabledState_Resource_Title = "AD Object Enabled State_dhcpAvocado"
                  ObjectClass                         = 'Computer'
                  Enabled                             = $false
                  #Credential_Enable_Computer_Object = $($un = 'CreateComputers0-T0'; [PSCredential]::New("$AD_NetBIOS\$un",$(Get-StoredCredential -Target $un | % 'Password')))
                }
                #endregion
                #region | AD Computers that host an Enterprise CA |
                @{ # pkiA-0 |
                  ADComputer_Resource_Title = "AD Computer_pkiA-0"
                  ComputerName              = 'pkiA-0' | ForEach-Object -Process {Get-ChildItem -ErrorAction 'SilentlyContinue' -Path $Statics -Recurse -Filter "*$_ ComputerName.txt"} | Get-Content
                  Path                      = "OU=Policy,OU=PK1,OU=Cs,OU=$LabelGamma,OU=Org,$AD_DN"
                  Description               = "System that hosts the Enterprise Subordinate CA"
                  DisplayName               = "Enterprise Subordinate CA Host"
                  DnsHostName               = "$('pkiA-0' | ForEach-Object -Process {Get-ChildItem -ErrorAction 'SilentlyContinue' -Path $Statics -Recurse -Filter "*$_ ComputerName.txt"} | Get-Content).$AD_DNS"
                  DomainController          = "$($NodeMgmtCname | ForEach-Object -Process {Get-ChildItem -ErrorAction 'SilentlyContinue' -Path $Statics -Recurse -Filter "*$_ ComputerName.txt"} | Get-Content).$AD_DNS"
                  #Location                         = "use the Microsoft-defined syntax for this Location attribute" # 
                  EnabledOnCreation         = $false
                  Manager                   = "CN=OverPrivDomainJoinT0,OU=Us,OU=Tier 0,OU=Org,$AD_DN"
                  RestoreFromRecycleBin     = $false      # Flip to $true in production. 
                  # ServicePrincipalNames           = Array of SPNs for this AD Computer object... if only I knew what an SPN was. 
                  # UserPrincipalName               = What would be the UPN of an AD Computer object? Why would the principal of a USER principal name apply to a COMPUTER object? Perhaps UPN should've been 'APN' or 'UAPN'. 
                  RbKCD               = @( # Resource-Based Kerberos Constrained Delegation
                    @{
                      SecondHopLandingCname = 'pki0-aia-cdp'
                      ResourceNameMaybe   = 'cifs'
                    }
                    @{
                      SecondHopLandingCname = 'fsEggroll'
                      ResourceNameMaybe   = 'cifs'
                    }
