                $un = [QuickMgmtCnameConversion]::CN(${DSC Authoring Station Mgmt Cname}) + ' ' + 544
                $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
                $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
                #endregion
                #endregion
                @{ # File |
                  Resource_Title           = "COPY OPERATION from General to Special for $NodeMgmtCname"
                  DestinationPath          = "$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 1-Special\$NodeMgmtCname\${Windows Server Image Index}\$VmOrdinal Ctrl 0 Loc 00~$VmColloquial.vhdx"
                  SourcePath               = $SourceFile.FullName
                  Force                    = $false
                  Type                     = 'File'
                  Credential               = $Credential
                  Ensure                   = 'Present'
