                      #endregion
                    }
                  )
                  $(${VLAN Title} = 'PUBG Continent'; ${Network Adapter Index} = '0'; ${Adapter Hardware Type} = [AdapterHardwareType]::Mc;
                    #region |  |
                    ${VLAN ID-Binary} = Get-Content -Path "$Statics\MaxIP\VLANs\${VLAN Title}.txt" -ErrorAction 'SilentlyContinue'
