                            $Resource_Title = "Advanced property of $InterfaceName on $NodeMgmtCname-Set value of property $RegistryKeyword to $RegistryValue" -replace '[^a-z0-9- _\.]','\'
                            # Send Buffer Size
                            @{
                              Resource_Title       = "Advanced property of $($InterfaceName -replace '[^a-z0-9- _\.]','\') on $NodeMgmtCname-Set value of property $($RegistryKeyword -replace '[^a-z0-9- _\.]','\') to $([System.String]$RegistryValue)"
                              NetworkAdapterName   = $NetworkAdapterName
                              RegistryKeyword      = $RegistryKeyword
                              RegistryValue        = $RegistryValue
                              PsDscRunAsCredential = $PsDscRunAsCredential
                            }
                          )
