                        }

                        <#
                          ${Default Gateway IPv4 Address} = [System.Environment]::GetEnvironmentVariables('Machine')["Default Gateway $_VLAN $AddressFamily Address"]
                          
                          ${_DNS Server IPv4 Address} = $ConfigurationData.AllNodes.Where({
                            $_.NodeCname -eq ${DSC Authoring Station Mgmt Cname}
                          }).'RESERVED IPv4 Addr-DnsServer Global'.IPv4Address
                          $path = "$Statics\IPs\0010 $vlan10\$DomainCtrl00Cname 8 $([aht]::Mc) IP Address.txt"
                          $IsPresent = Test-Path -Path $path
                          if ($IsPresent) {
                            ${DNS Server IPv4 Address in Binary} = Get-Content -Path $path
                            ${DNS Server IPv4 Address} = ConvertTo-DottedDecimalIP -IPAddress ${DNS Server IPv4 Address in Binary} | Select-Object -ExpandProperty 'IPAddressToString'
                          }
                        #>
                        #endregion
