                          ${Default Gateway IPv4 Address} = [System.Environment]::GetEnvironmentVariables('Machine')["Default Gateway $_VLAN $AddressFamily Address"]
                          
                          ${_DNS Server IPv4 Address} = $ConfigurationData.AllNodes.Where({
