          'Windows Features' = $(
            #region |  |
            #region | Credentials |
            $Target = "$NodeMgmtCname 544"
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $Credential = [PSCredential]::New($un,$pw)

            $Target = "$NodeMgmtCname 544"
            $HT = @{Target = $Target; Type = 'Generic'; Verbose = $false; ErrorAction = 'Stop'}
            $un = [QuickMgmtCnameConversion]::CN($NodeMgmtCname) + ' ' + 544
            $pw = Get-StoredCredential @HT | Select-Object -ExpandProperty 'Password'
            $PsDscRunAsCredential = [PSCredential]::New($un,$pw)
            #endregion
            ${DHCP HT} = ${Clone Me DHCP HT}.Clone()
            ${DHCP HT}['Resource_Title'] = ${DHCP HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${DHCP HT}.Add('Credential',$Credential)
            ${DHCP HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)

            ${RSAT-DHCP HT} = ${Clone Me RSAT-DHCP HT}.Clone()
            ${RSAT-DHCP HT}['Resource_Title'] = ${RSAT-DHCP HT}['Resource_Title'] -replace '%_NodeMgmtCname_%',$NodeMgmtCname
            ${RSAT-DHCP HT}.Add('Credential',$Credential)
            ${RSAT-DHCP HT}.Add('PsDscRunAsCredential',$PsDscRunAsCredential)
            #endregion
            if ( # Desktop Experience |
              -not (${Windows Server Image Index} % 2)) {
              @(
                ${DHCP HT}
                ${RSAT-DHCP HT}
              )
            } elseif ( # Server Core |
              ! (-not (${Windows Server Image Index} % 2))) {
