          #what was I thinking?! @{Name = 'DSC_CFG_ROOT'; Value = $env:DSC_CFG_ROOT; Ensure = 'Present'; IsPath = $false}
          # DO NOT SET THE 'DSC_CFG_ROOT' ENVIRONMENT VARIABLE WITH ANOTHER VARIABLE! 
          # @{Name = 'DSC_CFG_ROOT'; Value = $__DirectoryForDscConfigs; Ensure = 'Present'; IsPath = $false}
          # Going forward, the $__DirectoryForDscConfigs variable sets the 'DSC_CFG_ROOT' environment variable via unattend.xml. 
          # @{Name = 'Xeroxable VHDX Path-Index 2'; Value = "O:"; Ensure = 'Present'; IsPath = $false}
          $(@{Name = 'SystemModules';
              Value  = "$env:WinDir\System32\WindowsPowerShell\v1.0\Modules"
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'SysMods';
              Value  = "$env:WinDir\System32\WindowsPowerShell\v1.0\Modules"
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'SMs';
              Value  = "$env:WinDir\System32\WindowsPowerShell\v1.0\Modules"
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'ProgramModules';
              Value  = "$env:ProgramFiles\WindowsPowerShell\Modules"
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'ProgMods';
              Value  = "$env:ProgramFiles\WindowsPowerShell\Modules"
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'PMs';
              Value  = "$env:ProgramFiles\WindowsPowerShell\Modules"
              Ensure = 'Present'
              IsPath = $false
            }
          )

          # The only reason 'Statics' and 'AuthoredDscResourceModules' are getting set as System-level environment variables is because they're not
          # recognized within the DSC_FileDirectory[] property of the FileDirectory property of the VhdFile DSC Resource! 
          $(@{Name = 'Statics';
              Value  = $Statics
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'AuthoredDscResourceModules';
              Value  = $AuthoredDscResourceModules
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'regex literal DNS CNAME (Anchorless)';
              Value  = ${regex literal DNS CNAME (Anchorless)}
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'ResMod';
              Value  = $ResMod
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'MOFs';
              Value  = $MOFs
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'Pre-PKI CertFSOs';
              Value  = ${Pre-PKI CertFSOs}
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'VM Folder Path';
              Value  = $(
                ${HvH Disk CIM Instance} = Import-CliXml -Path "$env:DSC_CFG_ROOT\CliXmls\HvH Disk CIM Instance.clixml"
                ${HvH Partition HvH Disk CIM Instance} = Get-Disk -UniqueId ${HvH Disk CIM Instance}.UniqueId | Get-Partition
                ${HvH Volume HvH Partition HvH Disk CIM Instance} = Get-Volume -Partition (${HvH Partition HvH Disk CIM Instance})
                ${HvH Drive Letter} = [System.String]${HvH Volume HvH Partition HvH Disk CIM Instance}.DriveLetter + ':'
                "${HvH Drive Letter}\ProgramData\Microsoft\Windows\Hyper-V"
              )
              Ensure = 'Present'
              IsPath = $false
            }
          )
          $(@{Name = 'VHD Folder Path';
              Value  = $(
                ${HvH Disk CIM Instance} = Import-CliXml -Path "$env:DSC_CFG_ROOT\CliXmls\HvH Disk CIM Instance.clixml"
                ${HvH Partition HvH Disk CIM Instance} = Get-Disk -UniqueId ${HvH Disk CIM Instance}.UniqueId | Get-Partition
                ${HvH Volume HvH Partition HvH Disk CIM Instance} = Get-Volume -Partition (${HvH Partition HvH Disk CIM Instance})
                ${HvH Drive Letter} = [System.String]${HvH Volume HvH Partition HvH Disk CIM Instance}.DriveLetter + ':'
                "${HvH Drive Letter}\ProgramData\Microsoft\Windows\Virtual Hard Disks"
              )
              Ensure = 'Present'
              IsPath = $false
            }
          )
          #endregion
        )
      )
      'DSC_CFG_ROOT Directory Tree Set' = $(
        $SelfRef = $(
          ${Partial Paths 0} = @(
            'DSC\MOFs\Pendings'                 # meta.mof & .mof files that eventually get renamed to MetaConfig.mof & Pending.mof for the bootstrap process during VM spin-up
            'DSC\MOFs\Tshoot'                   # Mainly for the development of our custom authored DSC Resources
          )
          ${Partial Paths 1} = $(
            ${Partial Path Epochs} = @(
              #'DSC\MOFs\Epoch A_Pre-Document Encryption'        # Commands prior to the support of secure strings in the .MOF files
              #'DSC\MOFs\Epoch A_Pre-Credential'                 # Commands prior to restoring the Credential Manager, and therefore also prior to executing the ${Define ConfigurationData Variable} scriptblock for the 1st time. 
              'DSC\MOFs\Epoch_A__PreDocument_Encryption'        # Packed into the autounattend.xml file for the primordial unclustered Hyper-V Host / DSC Authoring Station
              #'DSC\MOFs\Epoch B_IdDef Builds'                  # Define random values generated once per bare-metal deployment.
              'DSC\MOFs\Epoch_B__HvH_with_VMs'                  # C:\_AA\DSC\MOFs\Epoch_B__HvH_with_VMs\Wave_00
              #'DSC\MOFs\Epoch C_VHDX Builds'                   # Generate VHDX files of guest OS instances
              'DSC\MOFs\Epoch_C__Cert_Exch'                     # C:\_AA\DSC\MOFs\Epoch_C__Cert_Exch\Wave_00
              #'DSC\MOFs\Epoch D_Push'                          # Push Server Epoch
              #'DSC\MOFs\Epoch E_Pull'                          # Pull Server Epoch
            )
            ${Mof Wave Dir Names} = [System.String[]]@(
              0..8 | ForEach-Object -Process {
                #"Wave__$(($_).ToString('00'))"
                "Wave_$(($_).ToString('00'))"
              }
            )
            foreach (${Partial Path Epoch} in ${Partial Path Epochs}) {
              foreach (${Mof Wave Dir Name} in ${Mof Wave Dir Names}) {
                Join-Path -Path ${Partial Path Epoch} -ChildPath ${Mof Wave Dir Name}
              }
            }
          )
          ${Partial Paths 2} = @(
            'DSC\Statics\PMs'                       # Statics contains text files that contain a single string whose value is changed with each deployment of the primordial original Hyper-V Host that doubles as a DSC push server
            'DSC\Statics\PMs\mas'                   # mas = MAC Address Space
            'DSC\Statics\VMs'                       # Hostnames of VMs
            'DSC\Statics\VMs\VHDs'                  # Empty VHDX files for eventual storage. Non-System disks!
            'DSC\Statics\CNOs'                      # Hostnames of Cluster Name Objects
            'DSC\Statics\Org Names'                 # Organizational Naming
            'DSC\Statics\HW\DSC Authoring Station'  # Hardware
            'DSC\Statics\GeoInfo'                   # Location/Culture/Geography/etc.
            'DSC\Statics\MaxIP'                     # Directory supporting advanced network configuration

            'DSC\ResMod'                        # DSC Resource modules stored in .ZIP files
            'modules\5.1'                       # Modules Directory: Non-DSC Resource PowerShell modules like 'NtObjectManager' and 'PSPKI' |
            'Installs'                          # Application files
            'Hyper-V Prep\Images'               # .img/.iso files of operating systems
            'Hyper-V Prep\VHDX 0-General'       # VHDXs loaded with files NOT specific to any CNAME and NOT specific to any MetaConfig.mof/Pending.mof
            'Hyper-V Prep\VHDX 1-Special'       # VHDXs loaded with files specific to a CNAME but NOT specific to any individual MetaConfig.mof/Pending.mof
            'Hyper-V Prep\VHDX 2-Unique'        # VHDXs loaded with the precise MetaConfig.mof/Pending.mof corresponding to the CNAME
            'Preboots'                          # 
          )
          ${Final Partial Paths} = ${Partial Paths 0} + ${Partial Paths 1} + ${Partial Paths 2}
        )

        $SelfR3f = $(
          $Folders = @(
            [System.IO.DirectoryInfo]"$Statics\MAC Address Space"
            [System.IO.DirectoryInfo]"$Statics\VHDs"
            [System.IO.DirectoryInfo]"$Statics\Org Names"
            [System.IO.DirectoryInfo]"$Statics\GeoInfo"
            [System.IO.DirectoryInfo]"$Statics\Accy"
            #[System.IO.DirectoryInfo]"$Statics\MaxIP\Physical Non-Removable PCIe Adapter MACs"
            [System.IO.DirectoryInfo]"$Statics\MaxIP\VLANs"
            [System.IO.DirectoryInfo]$ResMod
            [System.IO.DirectoryInfo]${Pre-PKI CertFSOs}
            [System.IO.DirectoryInfo]"$MOFs\Pendings"
            [System.IO.DirectoryInfo]"$MOFs\Tshoot"
            [System.IO.DirectoryInfo]"$MOFs\00 Hadean Pre-Document Encryption"
            [System.IO.DirectoryInfo]"$MOFs\01 Eoarchean Hyper-V Host with VMs"
            [System.IO.DirectoryInfo]"$MOFs\02 Paleoarchean Certificate Exchange"
            [System.IO.DirectoryInfo]"$env:DSC_CFG_ROOT\Installs\Modules\5.1"
            [System.IO.DirectoryInfo]"$env:DSC_CFG_ROOT\Hyper-V Prep\Images"
            [System.IO.DirectoryInfo]"$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 0-General"
            [System.IO.DirectoryInfo]"$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 1-Special"
            [System.IO.DirectoryInfo]"$env:DSC_CFG_ROOT\Hyper-V Prep\VHDX 2-Unique"
            [System.IO.DirectoryInfo]"$env:DSC_CFG_ROOT\Preboots"
          )
        )
        foreach ($Folder in $Folders) {
          @{
            Resource_Title       =     "Directory Tree $($Folder.FullName -replace '[^a-z0-9- _\.]','\') under DSC_CFG_ROOT"
            DestinationPath      =     "$Folder"
            Type                 =     'Directory'
            Force                =     $true
            Ensure               =     'Present'
          }
        }
      )
      Apps = $(
        #region |  |
        #endregion
        @{
          'PowerShell 7' = $(
            #region |  |
            #endregion
            @{
              Logging = $(
                #region |  |
                $BasePath = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShellCore'
                #endregion
                @(
                  $($ValueName = 'EnableScriptBlockLogging'; $Key = "$BasePath\ScriptBlockLogging"; $ValueData = '1'; 
                    @{
                      Resource_Title = "PowerShell 7 ScriptBlock Logging"
                      Key            = $Key
                      ValueName      = $ValueName
                      ValueData      = $ValueData
                      ValueType      = 'String'
                      Force          = $true
                      Ensure         = 'Present'
                    }
                  )
                  $($ValueName = 'EnableModuleLogging'; $Key = "$BasePath\ModuleLogging"; $ValueData = '1'; 
                    @{
                      Resource_Title = "PowerShell 7 Module Logging"
                      Key            = $Key
                      ValueName      = $ValueName
                      ValueData      = $ValueData
                      ValueType      = 'String'
                      Force          = $true
                      Ensure         = 'Present'
                    }
                  )
                  $($ValueName = 'EnableTranscribing'; $Key = "$BasePath\Transcription"; $ValueData = '1'; 
                    @{
                      Resource_Title = "PowerShell 7 Transcription 1"
                      Key            = $Key
                      ValueName      = $ValueName
                      ValueData      = $ValueData
